INSERT INTO power VALUES (222,'Psychofeedback','Psychometabolism',NULL,NULL,'Egoist 5, psychic warrior 5','Visual','1 standard action','Personal','You',NULL,NULL,'1 round/level (D)',NULL,'9',NULL,'Boost Str, Dex, or Con at the expense of one or more other scores.',NULL,'\n      <p>You can readjust your body to boost one physical ability score at the expense of one or more other scores. Select one ability score you would like to boost, and increase it by the same amount that you decrease one or more other scores. All score decreases are treated as a special form of ability damage, called ability burn, which cannot be magically or psionically healed-it goes away only through natural healing.</p>\n      <p>You can boost your Strength, Dexterity or Constitution score by an amount equal to your manifester level (or any lesser amount), assuming you can afford to burn your other ability scores to such an extent.</p>\n      <p>When the duration of this power expires, your ability boost also ends, but your ability burn remains until it is healed naturally.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Psychofeedback\" level=\"5\"><p><h5>Psychofeedback</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Egoist 5, psychic warrior 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>You can readjust your body to boost one physical ability score at the expense of one or more other scores. Select one ability score you would like to boost, and increase it by the same amount that you decrease one or more other scores. All score decreases are treated as a special form of ability damage, called ability burn, which cannot be magically or psionically healed-it goes away only through natural healing.</p><p>You can boost your Strength, Dexterity or Constitution score by an amount equal to your manifester level (or any lesser amount), assuming you can afford to burn your other ability scores to such an extent.</p><p>When the duration of this power expires, your ability boost also ends, but your ability burn remains until it is healed naturally.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersG-P');
INSERT INTO power VALUES (223,'Quintessence','Metacreativity','Creation',NULL,'Shaper 4','Material; see text','1 round','0 ft.',NULL,NULL,'1-inch-diameter dollop of quintessence; see text','Instantaneous','None','7','No','You collapse a bit of time into a physical substance.',NULL,'\n      <p>You collapse a bit of time from the continuum, forming a 1-ounce dollop of thick, gooey material called quintessence. This substance shimmers like a silver mirror when viewed from some angles but is transparent from other viewpoints. You can smooth a dollop of quintessence around any extremely small object.</p>\n      <p>Objects sealed within quintessence are protected from the effects of time; in practical terms, they enter a state of stasis. Living flesh with only partial contact with quintessence is also partially pulled out of the time stream (the manifester is immune to this effect). This disruption deals 1 point of damage per round beginning 10 rounds after partial contact occurs.</p>\n      <p>Quintessence can be manually scraped away from a protected object, freeing it to rejoin the time stream. When you do this, there is a 75% chance that the quintessence evaporates back into the continuum. Otherwise, it coalesces again into a 1-inch-diameter bead, available for later use.</p>\n      <p>Large quantities of quintessence could theoretically be gathered to preserve large items or structures (or even a complete living creature; if completely immersed, a living creature would not take the damage associated with partial contact). However, psionic characters and creatures are generally loath to do so because accumulations of quintessence weighing 1 pound or more hinder psionic activity within a 5-foot radius of the accumulation: Powers require twice as many power points to manifest, unless the manifester makes a successful Will save (DC 16) each time he or she attempts to manifest a power. Also in these circumstances, manifesting a psi-like ability that is usable at will is a full-round action rather than a standard action.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Quintessence\" level=\"5\"><p><h5>Quintessence</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Metacreativity (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Shaper 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>1-inch-diameter dollop of quintessence; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>You collapse a bit of time from the continuum, forming a 1-ounce dollop of thick, gooey material called quintessence. This substance shimmers like a silver mirror when viewed from some angles but is transparent from other viewpoints. You can smooth a dollop of quintessence around any extremely small object.</p><p>Objects sealed within quintessence are protected from the effects of time; in practical terms, they enter a state of stasis. Living flesh with only partial contact with quintessence is also partially pulled out of the time stream (the manifester is immune to this effect). This disruption deals 1 point of damage per round beginning 10 rounds after partial contact occurs.</p><p>Quintessence can be manually scraped away from a protected object, freeing it to rejoin the time stream. When you do this, there is a 75% chance that the quintessence evaporates back into the continuum. Otherwise, it coalesces again into a 1-inch-diameter bead, available for later use.</p><p>Large quantities of quintessence could theoretically be gathered to preserve large items or structures (or even a complete living creature; if completely immersed, a living creature would not take the damage associated with partial contact). However, psionic characters and creatures are generally loath to do so because accumulations of quintessence weighing 1 pound or more hinder psionic activity within a 5-foot radius of the accumulation: Powers require twice as many power points to manifest, unless the manifester makes a successful Will save (DC 16) each time he or she attempts to manifest a power. Also in these circumstances, manifesting a psi-like ability that is usable at will is a full-round action rather than a standard action.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (224,'Read Thoughts','Telepathy',NULL,'Mind-Affecting','Telepath 2','Mental','1 standard action','60 ft.',NULL,'Cone-shaped emanation centered on you',NULL,'Concentration, up to 1 min./level (D)','Will negates; see text','3','No','Detect surface thoughts of creatures in range.',NULL,'\n      <p>You know the surface thoughts of the mind of any creature in the area that fails a Will save. A target that succeeds on its save is not affected by this manifestation of the power, even if it leaves the area and then reenters the area before the duration expires.</p>\n      <p>Creatures of animal intelligence have simple, instinctual thoughts that you can pick up. If you read the thoughts of a creature with an Intelligence of 26 or higher (and at least 10 points higher than your own Intelligence score), you are stunned for 1 round and the power ends. This power does not let you pinpoint the location of an affected mind if you don\'t have line of sight to the subject.</p>\n      <p>Each round, you can turn to use this power in a new area. The power can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Read Thoughts\" level=\"5\"><p><h5>Read Thoughts</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Telepath 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Mental<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>You know the surface thoughts of the mind of any creature in the area that fails a Will save. A target that succeeds on its save is not affected by this manifestation of the power, even if it leaves the area and then reenters the area before the duration expires.</p><p>Creatures of animal intelligence have simple, instinctual thoughts that you can pick up. If you read the thoughts of a creature with an Intelligence of 26 or higher (and at least 10 points higher than your own Intelligence score), you are stunned for 1 round and the power ends. This power does not let you pinpoint the location of an affected mind if you don\'t have line of sight to the subject.</p><p>Each round, you can turn to use this power in a new area. The power can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (225,'Reality Revision','Clairsentience',NULL,NULL,'Psion/wilder 9','Visual','1 standard action','See text','See text','See text','See text','See text','See text','17, XP','See text','As bend reality, but fewer limits.','The minimum XP cost for manifesting Reality revision is 5,000','\n      <p>As <i>bend reality</i>, but with more farreaching effects. A <i>Reality revision</i> can produce any one of the following effects.</p>\n      <ul>\n <li> Duplicate any psion power of 8th level or lower, provided the power is not prohibited to you.</li>\n <li> Duplicate any other power (but not a spell) of 6th level or lower, such as a psychic warrior power.</li>\n <li> Duplicate any psion power of 7th level or lower even if it\'s a power prohibited to you.</li>\n <li> Undo the harmful effects of many other powers, such as <i>microcosm</i>,  <i>geas/quest</i>,  or <i>insanity</i>.</li>\n <li> Create a nonpsionic item of up to 25,000 gp in value.</li>\n <li> Create a psionic item, or add to the powers of an existing psionic item (see XP cost below).</li>\n <li> Grant a creature a +1 inherent bonus to an ability score. Two to five <i>reality revisions</i> manifested in immediate succession can grant a creature a +2 to +5 inherent bonus to an ability score. Inherent bonuses are instantaneous, so they cannot be negated or dispelled. An inherent bonus cannot exceed +5 for a single ability score. Inherent bonuses to a particular ability score do not stack; only the best one applies.</li>\n <li> Remove injuries and afflictions. A single <i>Reality revision</i> can aid one creature per manifester level, and all subjects are cured of the same kind of affliction.</li>\n</ul>\n      <p><i>Reality revision</i> can not restore the experience point loss from manifesting a power or casting a spell, or the level or  Constitution loss from being returned to life by those effects that reduce level or Constitution.</p>\n      <ul>\n <li> Revive the dead. <i>Reality revision</i> can bring a dead creature back to life by duplicating a <i>resurrection</i> spell. This power can revive a dead creature whose body has been destroyed, but the task takes two manifestations of <i>reality revision</i>, one to recreate the body and another to infuse the body with life again. <i>Reality revision</i> cannot prevent a character who is brought back to life from losing a level.</li>\n <li> Transport travelers. This power can lift one creature per manifester level from anywhere on any plane and place those creatures anywhere else on any plane regardless of local conditions. An unwilling target gets a Will save to negate the effect, and power resistance (if any) applies.</li>\n <li> Undo misfortune. <i>Reality revision</i> can undo a single recent event. Manifesting the power forces a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. The reroll, however, may be as bad as or worse than the original roll. An unwilling target gets a Will save to negate the effect, and power resistance (if any) applies.</li>\n</ul>\n      <p>You can try to use <i>Reality revision</i> to produce more powerful effects than these, but doing so is dangerous. The manifestation may pervert your intent into a literal but undesirable fulfillment or only a partial fulfillment.</p>\n      <p>Duplicated powers allow saves and power resistance as normal (but save DCs are calculated as though the power is 9th level).</p>\n      <p>XP. When a manifestation duplicates a power that has an XP cost, you must pay 5,000 XP or that cost, whichever is more. When a manifestation creates or improves a psionic item, you must pay twice the normal XP cost for crafting or improving the item, plus an additional 5,000 XP.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Reality Revision\" level=\"5\"><p><h5>Reality Revision</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>17, XP<br/></td></tr></table><p>As <i>bend reality</i>, but with more farreaching effects. A <i>Reality revision</i> can produce any one of the following effects.</p><ul>\n <li> Duplicate any psion power of 8th level or lower, provided the power is not prohibited to you.</li>\n <li> Duplicate any other power (but not a spell) of 6th level or lower, such as a psychic warrior power.</li>\n <li> Duplicate any psion power of 7th level or lower even if it\'s a power prohibited to you.</li>\n <li> Undo the harmful effects of many other powers, such as <i>microcosm</i>,  <i>geas/quest</i>,  or <i>insanity</i>.</li>\n <li> Create a nonpsionic item of up to 25,000 gp in value.</li>\n <li> Create a psionic item, or add to the powers of an existing psionic item (see XP cost below).</li>\n <li> Grant a creature a +1 inherent bonus to an ability score. Two to five <i>reality revisions</i> manifested in immediate succession can grant a creature a +2 to +5 inherent bonus to an ability score. Inherent bonuses are instantaneous, so they cannot be negated or dispelled. An inherent bonus cannot exceed +5 for a single ability score. Inherent bonuses to a particular ability score do not stack; only the best one applies.</li>\n <li> Remove injuries and afflictions. A single <i>Reality revision</i> can aid one creature per manifester level, and all subjects are cured of the same kind of affliction.</li>\n</ul><p><i>Reality revision</i> can not restore the experience point loss from manifesting a power or casting a spell, or the level or  Constitution loss from being returned to life by those effects that reduce level or Constitution.</p><ul>\n <li> Revive the dead. <i>Reality revision</i> can bring a dead creature back to life by duplicating a <i>resurrection</i> spell. This power can revive a dead creature whose body has been destroyed, but the task takes two manifestations of <i>reality revision</i>, one to recreate the body and another to infuse the body with life again. <i>Reality revision</i> cannot prevent a character who is brought back to life from losing a level.</li>\n <li> Transport travelers. This power can lift one creature per manifester level from anywhere on any plane and place those creatures anywhere else on any plane regardless of local conditions. An unwilling target gets a Will save to negate the effect, and power resistance (if any) applies.</li>\n <li> Undo misfortune. <i>Reality revision</i> can undo a single recent event. Manifesting the power forces a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. The reroll, however, may be as bad as or worse than the original roll. An unwilling target gets a Will save to negate the effect, and power resistance (if any) applies.</li>\n</ul><p>You can try to use <i>Reality revision</i> to produce more powerful effects than these, but doing so is dangerous. The manifestation may pervert your intent into a literal but undesirable fulfillment or only a partial fulfillment.</p><p>Duplicated powers allow saves and power resistance as normal (but save DCs are calculated as though the power is 9th level).</p><p><i>XP Cost:</i> The minimum XP cost for manifesting <i>Reality revision</i> is 5,000</p><p>XP. When a manifestation duplicates a power that has an XP cost, you must pay 5,000 XP or that cost, whichever is more. When a manifestation creates or improves a psionic item, you must pay twice the normal XP cost for crafting or improving the item, plus an additional 5,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (226,'Recall Agony','Clairsentience',NULL,'Mind-Affecting','Psion/wilder 2','Material','1 standard action','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'Instantaneous','Will half','3','Yes','Foe takes 2d6 damage.',NULL,'\n      <p>The fabric of time parts to your will, revealing wounds your foe has received in the past (or has yet to receive). That foe takes 2d6 points of damage as the past (or future) impinges briefly on the present.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d6 points. For each extra 2d6 points of damage, this power\'s save DC increases by 1.</p><p/>\n','\n      <div topic=\"Recall Agony\" level=\"5\"><p><h5>Recall Agony</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>The fabric of time parts to your will, revealing wounds your foe has received in the past (or has yet to receive). That foe takes 2d6 points of damage as the past (or future) impinges briefly on the present.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d6 points. For each extra 2d6 points of damage, this power\'s save DC increases by 1.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (227,'Recall Death','Clairsentience',NULL,'Death, Mind-Affecting','Psion/wilder 8','Material','1 standard action','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'Instantaneous','Will partial; see text','15','Yes','Subject dies or takes 5d6 damage.',NULL,'\n      <p>As <i>recall agony</i>, except the wounds revealed by folding the fourth dimension are potentially fatal. If the target fails its Will save. it dies. If the save succeeds, the target instead takes 5d6 points of damage.</p>\n      <p/>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d6 points. For each extra 2d6 points of damage, this power\'s save DC increases by 1.</p><p/>\n','\n      <div topic=\"Recall Death\" level=\"5\"><p><h5>Recall Death</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience [Death, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>15<br/></td></tr></table><p>As <i>recall agony</i>, except the wounds revealed by folding the fourth dimension are potentially fatal. If the target fails its Will save. it dies. If the save succeeds, the target instead takes 5d6 points of damage.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (228,'Reddopsi','Psychokinesis',NULL,NULL,'Kineticist 7','Auditory, mental, and olfactory','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)',NULL,'13',NULL,NULL,NULL,'\n      <p>When you manifest <i>reddopsi</i>,  powers targeted against you rebound to affect the original manifester. This effect reverses powers that have only you as a target (except <i>dispel psionics</i> and similar powers or effects). Powers that affect an area and those that produce effects can\'t be reversed. <i>Reddopsi</i> also can\'t reverse any power with a range of touch.</p>\n      <p>Should you rebound a power back against a manifester who also is protected by <i>reddopsi</i>, the power rebounds once more upon you.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Reddopsi\" level=\"5\"><p><h5>Reddopsi</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Kineticist 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory, mental, and olfactory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>13<br/></td></tr></table><p>When you manifest <i>reddopsi</i>,  powers targeted against you rebound to affect the original manifester. This effect reverses powers that have only you as a target (except <i>dispel psionics</i> and similar powers or effects). Powers that affect an area and those that produce effects can\'t be reversed. <i>Reddopsi</i> also can\'t reverse any power with a range of touch.</p><p>Should you rebound a power back against a manifester who also is protected by <i>reddopsi</i>, the power rebounds once more upon you.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (229,'Remote View Trap','Clairsentience',NULL,'Electricity','Psion/wilder 6','Mental and visual','1 standard action','Personal','You',NULL,NULL,'24 hours + 1 hour/level','Will half; see text','11','No','Deal 8d6 points electricity damage to those who seek to view you at a distance.',NULL,'\n      <p>When others use <i>clairvoyant sense</i>, <i>remote viewing</i>, or other means of scrying you from afar, your prepared trap gives them a nasty surprise. If the scryer fails its saving throw, you are undetected. Moreover, the would-be observer takes 8d6 points of electricity damage. If the scryer makes its saving throw, it takes only 4d6 points of electricity damage and is able to observe you normally. Either way, you are aware of the attempt to view you, but not of the viewer or the viewer\'s location. It is possible that you might recognize the quasireal viewpoint of someone using the <i>remote viewing</i> power if you could pierce its <i>invisibility</i> (which is true for <i>remote viewing</i> whether or not you use this power).</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Remote View Trap\" level=\"5\"><p><h5>Remote View Trap</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience [Electricity]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Mental and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours + 1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>11<br/></td></tr></table><p>When others use <i>clairvoyant sense</i>, <i>remote viewing</i>, or other means of scrying you from afar, your prepared trap gives them a nasty surprise. If the scryer fails its saving throw, you are undetected. Moreover, the would-be observer takes 8d6 points of electricity damage. If the scryer makes its saving throw, it takes only 4d6 points of electricity damage and is able to observe you normally. Either way, you are aware of the attempt to view you, but not of the viewer or the viewer\'s location. It is possible that you might recognize the quasireal viewpoint of someone using the <i>remote viewing</i> power if you could pierce its <i>invisibility</i> (which is true for <i>remote viewing</i> whether or not you use this power).</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (230,'Remote Viewing','Clairsentience','Scrying, see text',NULL,'Seer 4','Mental','1 hour','See text',NULL,NULL,'Quasi-real viewpoint','1 min./level (D)','Will negates','7, XP','Yes','See, hear, and potentially interact with subjects at a distance.5Clairtangent Hand: Emulate far hand at a distance.','20 XP.','\n      <p>You send your mind across space and dimensions, forming it into a quasireal viewpoint from which you can see and hear some creature located at any distance from you, even if planar boundaries separate you. If the subject succeeds on a Will save, the <i>remote viewing</i> attempt fails, and you can\'t attempt to view that creature again for at least 24 hours. The difficulty of the save depends on how well you know the subject and what sort of physical connection (if any) you have to that creature. Furthermore, if the subject is on another plane, it gets a +5 bonus on its Will save.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Knowledge</b><br/></td> <td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>None*<br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Secondhand (you have heard of the subject)<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Firsthand (you have met the subject)<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Familiar (you know the subject well)<br/></td>\n<td>-5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">*You must have some sort of connection to a creature you have no knowledge of.<br/></td>\n\n</tr>\n</table>\n      <p/>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Connection</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Likeness or picture<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Possession or garment<br/></td>\n<td>-4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Body part, lock of hair, bit of nail, etc.<br/></td>\n<td>-10<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Subject on another plane<br/></td>\n<td>+5<br/></td>\n\n</tr>\n</table>\n      <p>If the subject fails its Will save, your mind coalesces a quasi-real viewpoint near enough to the subject to see and hear the subject and its immediate surroundings (up 30 feet in all directions away from the subject).</p>\n      <p>While the <i>remote viewing</i> lasts, your real body remains unmoving and unaware of your actual surroundings. On the other hand, your quasi-real viewpoint is treated in some ways as if it were an invisible <i>ectoplasmic form</i> of yourself, except as follows. This power is of the Scrying subdiscipline, but use the following information in place of the standard scrying sensor. As a quasi-real viewpoint, you can speak (though your voice is whispery).</p>\n      <p>You may potentially be sensed by the subject of your viewing (subjects who can see or sense invisible or hidden creatures automatically sense you; otherwise you make a Hide check with a +40 bonus to escape detection if immobile, or a +20 bonus if moving). You could be attacked (although if you become subject to <i>dispel psionics</i>, the <i>remote viewing</i> simply ends). If the subject moves, you can attempt to follow it at a speed of 20 feet, though if it gets farther than 30 feet from you (or you move farther than 30 feet from it), the power ends.</p>\n      <p>You can attempt to manifest one power through your quasi-real viewpoint, but you must make a Concentration check (DC 20 + level of the power you wish to manifest) to succeed. Manifesting (or attempting and failing to manifest) a power immediately ends the <i>remote viewing</i>.</p>\n      <p>Furthermore, all powers from your quasi-real viewpoint cost twice the usual number of power points (you can\'t exceed the power point limit set by your manifester level, so you are restricted to manifesting lower-level powers than you otherwise could). Power points you spend as a quasireal viewpoint are drained from your real body.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Remote Viewing\" level=\"5\"><p><h5>Remote Viewing</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience (Scrying, see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Seer 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Mental<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 hour<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Quasi-real viewpoint<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7, XP<br/></td></tr></table><p>You send your mind across space and dimensions, forming it into a quasireal viewpoint from which you can see and hear some creature located at any distance from you, even if planar boundaries separate you. If the subject succeeds on a Will save, the <i>remote viewing</i> attempt fails, and you can\'t attempt to view that creature again for at least 24 hours. The difficulty of the save depends on how well you know the subject and what sort of physical connection (if any) you have to that creature. Furthermore, if the subject is on another plane, it gets a +5 bonus on its Will save.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Knowledge</b><br/></td> <td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>None*<br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Secondhand (you have heard of the subject)<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Firsthand (you have met the subject)<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Familiar (you know the subject well)<br/></td>\n<td>-5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">*You must have some sort of connection to a creature you have no knowledge of.<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Connection</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Likeness or picture<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Possession or garment<br/></td>\n<td>-4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Body part, lock of hair, bit of nail, etc.<br/></td>\n<td>-10<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Subject on another plane<br/></td>\n<td>+5<br/></td>\n\n</tr>\n</table><p>If the subject fails its Will save, your mind coalesces a quasi-real viewpoint near enough to the subject to see and hear the subject and its immediate surroundings (up 30 feet in all directions away from the subject).</p><p>While the <i>remote viewing</i> lasts, your real body remains unmoving and unaware of your actual surroundings. On the other hand, your quasi-real viewpoint is treated in some ways as if it were an invisible <i>ectoplasmic form</i> of yourself, except as follows. This power is of the Scrying subdiscipline, but use the following information in place of the standard scrying sensor. As a quasi-real viewpoint, you can speak (though your voice is whispery).</p><p>You may potentially be sensed by the subject of your viewing (subjects who can see or sense invisible or hidden creatures automatically sense you; otherwise you make a Hide check with a +40 bonus to escape detection if immobile, or a +20 bonus if moving). You could be attacked (although if you become subject to <i>dispel psionics</i>, the <i>remote viewing</i> simply ends). If the subject moves, you can attempt to follow it at a speed of 20 feet, though if it gets farther than 30 feet from you (or you move farther than 30 feet from it), the power ends.</p><p>You can attempt to manifest one power through your quasi-real viewpoint, but you must make a Concentration check (DC 20 + level of the power you wish to manifest) to succeed. Manifesting (or attempting and failing to manifest) a power immediately ends the <i>remote viewing</i>.</p><p>Furthermore, all powers from your quasi-real viewpoint cost twice the usual number of power points (you can\'t exceed the power point limit set by your manifester level, so you are restricted to manifesting lower-level powers than you otherwise could). Power points you spend as a quasireal viewpoint are drained from your real body.</p><p><i>XP Cost:</i> 20 XP.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (231,'Restoration, Psionic','Psychometabolism','Healing',NULL,'Egoist 6','Material','3 rounds','Touch','Creature touched',NULL,NULL,'Instantaneous','Will negates (harmless)','11','Yes (harmless)',NULL,NULL,'\n      <p>This power cures all ability damage, and it restores all points drained from a single ability score (your choice if more than one score is drained). It also eliminates any fatigue or exhaustion suffered by the target. <i>Restoration</i> does not restore levels or Constitution points lost due to death.</p>\n      <p><i>Restoration</i> can remove negative levels. It can also restore one level to a creature who has had a level drained, if the number of days since the creature lost the level is equal to or less than your manifester level. In such a case, <i>Restoration</i> brings the creature up to the minimum number of experience points necessary to advance it to the next higher level, gaining it an additional Hit Die and level benefits accordingly.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Restoration, Psionic\" level=\"5\"><p><h5>Restoration, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Egoist 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>3 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>11<br/></td></tr></table><p>This power cures all ability damage, and it restores all points drained from a single ability score (your choice if more than one score is drained). It also eliminates any fatigue or exhaustion suffered by the target. <i>Restoration</i> does not restore levels or Constitution points lost due to death.</p><p><i>Restoration</i> can remove negative levels. It can also restore one level to a creature who has had a level drained, if the number of days since the creature lost the level is equal to or less than your manifester level. In such a case, <i>Restoration</i> brings the creature up to the minimum number of experience points necessary to advance it to the next higher level, gaining it an additional Hit Die and level benefits accordingly.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (232,'Restore Extremity','Psychometabolism','Healing',NULL,'Egoist 5','Auditory','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Will half (harmless)','9','Yes (harmless)','Return a lost digit, limb, or other appendage to subject.6Restoration, Psionic: Restores level and ability score drains.7Fission: You briefly duplicate yourself.8Fusion: You combine your abilities and form with another.9Metamorphosis, Greater: Assume shape of any nonunique creature or object each round.',NULL,'\n      <p>You restore a severed extremity to a creature that has lost a digit, hand, arm, leg, or even its head. This power does not restore life, but it returns a lost extremity to a living or dead creature if the creature is otherwise mostly intact. The original extremity need not be present when this power is manifested; a new extremity is created by the power. If a head is restored to a body, the original head (if not already destroyed) loses all spark of identity, and can be considered so much dead tissue.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Restore Extremity\" level=\"5\"><p><h5>Restore Extremity</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Egoist 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will half (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>You restore a severed extremity to a creature that has lost a digit, hand, arm, leg, or even its head. This power does not restore life, but it returns a lost extremity to a living or dead creature if the creature is otherwise mostly intact. The original extremity need not be present when this power is manifested; a new extremity is created by the power. If a head is restored to a body, the original head (if not already destroyed) loses all spark of identity, and can be considered so much dead tissue.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (233,'Retrieve','Psychoportation','Teleportation',NULL,'Psion/wilder 6','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One object you can hold or carry in one hand, weighing up to 10 lb./level',NULL,NULL,'Instantaneous','Will negates; see text','11','No','Teleport to your hand an item you can see.',NULL,'\n      <p>You automatically teleport an item you can see within range directly to your hand. If the object is in the possession of an opponent, it comes to your hand if your opponent fails a Will save.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, the weight limit of the target increases by 10 pounds.</p><p/>\n','\n      <div topic=\"Retrieve\" level=\"5\"><p><h5>Retrieve</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One object you can hold or carry in one hand, weighing up to 10 lb./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>11<br/></td></tr></table><p>You automatically teleport an item you can see within range directly to your hand. If the object is in the possession of an opponent, it comes to your hand if your opponent fails a Will save.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, the weight limit of the target increases by 10 pounds.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (234,'Schism','Telepathy',NULL,'Mind-Affecting','Telepath 4','Auditory and visual','1 standard action','Personal','You',NULL,NULL,'1 round/level (D)',NULL,'7',NULL,'Your partitioned mind can manifest lower level powers.5Metaconcert: Mental concert of two or more increases the total power of the participants.',NULL,'\n      <p>Your mind splits into two independent parts. Each part functions in complete autonomy, like two characters in one body. Your new \'second mind\' does not control your body physically but is free to take one standard action in each round if the action is purely mental (such as manifesting a power) in the same round you take your normal actions.</p>\n      <p>Your second mind can manifest powers using your power point reserve, but only as if your manifester level were six lower than it is. Your second mind doesn\'t provoke attacks of opportunity when manifesting a power, because doing so doesn\'t distract your primary mind.</p>\n      <p>Your second mind takes its first action on your turn in the round after <i>schism</i> is manifested.</p>\n      <p>Both your minds communicate with each other telepathically. If you are subject to a compulsion or charm effect while you are of two minds, make a second saving throw if you fail the first. If you fail both, then the <i>schism</i> ends and you are affected normally by the power. If you fail just one, the <i>schism</i> ends immediately, but you are not subject to the compulsion or charm.</p>\n      <p>Your second mind does not gain any advantages if you are subject to a <i>haste</i> effect, although you gain the overall standard benefits.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Schism\" level=\"5\"><p><h5>Schism</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Telepath 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>Your mind splits into two independent parts. Each part functions in complete autonomy, like two characters in one body. Your new \'second mind\' does not control your body physically but is free to take one standard action in each round if the action is purely mental (such as manifesting a power) in the same round you take your normal actions.</p><p>Your second mind can manifest powers using your power point reserve, but only as if your manifester level were six lower than it is. Your second mind doesn\'t provoke attacks of opportunity when manifesting a power, because doing so doesn\'t distract your primary mind.</p><p>Your second mind takes its first action on your turn in the round after <i>schism</i> is manifested.</p><p>Both your minds communicate with each other telepathically. If you are subject to a compulsion or charm effect while you are of two minds, make a second saving throw if you fail the first. If you fail both, then the <i>schism</i> ends and you are affected normally by the power. If you fail just one, the <i>schism</i> ends immediately, but you are not subject to the compulsion or charm.</p><p>Your second mind does not gain any advantages if you are subject to a <i>haste</i> effect, although you gain the overall standard benefits.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (235,'Second Chance','Clairsentience',NULL,NULL,'Seer 5','Mental','1 standard action','Personal','You',NULL,NULL,'1 round/level or until discharged',NULL,'9',NULL,'Gain a reroll.6Precognition, Greater: Gain +4 insight bonus to one roll.7Fate of One: Reroll any roll you just failed.8Hypercognition: You can deduce almost anything.9Metafaculty: You learn details about any one creature.',NULL,'\n      <p>You take a hand in influencing the probable outcomes of your immediate environment. You see the many alternative branches that reality could take in the next few seconds, and with this foreknowledge you gain the ability to reroll one attack roll, one saving throw, one ability check, or one skill check each round. You must take the result of the reroll, even if it\'s worse than the original roll. You do not have to make another roll if satisfied with your original roll.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Second Chance\" level=\"5\"><p><h5>Second Chance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Seer 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Mental<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level or until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>You take a hand in influencing the probable outcomes of your immediate environment. You see the many alternative branches that reality could take in the next few seconds, and with this foreknowledge you gain the ability to reroll one attack roll, one saving throw, one ability check, or one skill check each round. You must take the result of the reroll, even if it\'s worse than the original roll. You do not have to make another roll if satisfied with your original roll.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (236,'Sense Link','Telepathy',NULL,'Mind-Affecting','Psion/wilder 1','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One willing creature',NULL,NULL,'Concentration, up to 1min./level',NULL,'1',NULL,'You sense what the subject senses (single sense).',NULL,'\n      <p>You perceive what the subject creature perceives using its sight, hearing, taste, or smell. Only one sense is linked, and you cannot switch between senses with the same manifestation.</p>\n      <p>You make any skill checks involving senses, such as Spot or Listen, as the subject, and only within the subject\'s field of view. You lose your Dexterity bonus to AC while directly sensing what the subject senses.</p>\n      <p>Once <i>sense link</i> is manifested, the link persists even if the subject moves out of the range of the original manifestation (but the link does not work across planes). You do not control the subject, nor can you communicate with it by means of this power.</p>\n      <p>The strength of the subject\'s linked sense could be enhanced by other powers or items, allowing you the same enhanced sense. You are subject to any gaze attack affecting the subject creature (if you linked vision). If you are blinded or deafened, or suffer some other sensory deprivation, the linked creature functions as an independent sensory organ, and provides you the benefit of the linked sense from its perspective while this power\'s duration lasts.</p>\n    ','<p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. If you spend 2 additional power points, you can have the subject perceive one of your senses instead of the other way around.</p><p>2. If you spend 4 additional power points, you can link to a second sense of the same subject.</p><p/>\n','\n      <div topic=\"Sense Link\" level=\"5\"><p><h5>Sense Link</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One willing creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>You perceive what the subject creature perceives using its sight, hearing, taste, or smell. Only one sense is linked, and you cannot switch between senses with the same manifestation.</p><p>You make any skill checks involving senses, such as Spot or Listen, as the subject, and only within the subject\'s field of view. You lose your Dexterity bonus to AC while directly sensing what the subject senses.</p><p>Once <i>sense link</i> is manifested, the link persists even if the subject moves out of the range of the original manifestation (but the link does not work across planes). You do not control the subject, nor can you communicate with it by means of this power.</p><p>The strength of the subject\'s linked sense could be enhanced by other powers or items, allowing you the same enhanced sense. You are subject to any gaze attack affecting the subject creature (if you linked vision). If you are blinded or deafened, or suffer some other sensory deprivation, the linked creature functions as an independent sensory organ, and provides you the benefit of the linked sense from its perspective while this power\'s duration lasts.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. If you spend 2 additional power points, you can have the subject perceive one of your senses instead of the other way around.</p><p>2. If you spend 4 additional power points, you can link to a second sense of the same subject.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (237,'Sense Link, Forced','Telepathy',NULL,'Mind-Affecting','Psion/wilder 2','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One willing creature',NULL,NULL,'Concentration, up to 1min./level','Will negates','3','Yes','Sense what subject senses.',NULL,'\n      <p>As <i>sense link</i>,  except you can use this power on any creature (willing or unwilling), and this power can\'t be augmented.</p>\n      <p/>\n    ','<p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. If you spend 2 additional power points, you can have the subject perceive one of your senses instead of the other way around.</p><p>2. If you spend 4 additional power points, you can link to a second sense of the same subject.</p><p/>\n','\n      <div topic=\"Sense Link, Forced\" level=\"5\"><p><h5>Sense Link, Forced</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>As <i>sense link</i>,  except you can use this power on any creature (willing or unwilling), and this power can\'t be augmented.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (238,'Sensitivity to Psychic Impressions','Clairsentience',NULL,NULL,'Seer 2','Auditory and material','1 hour','Close (25 ft. + 5 ft./2 levels)',NULL,'Spread with a radius of 25 ft. + 5 ft./2 levels, centered on you',NULL,'Concentration, up to 10 min./level','None','3','No','You can find out about an area\'s past.3Escape Detection: You become difficult to detect with clairsentience powers.',NULL,'\n      <p>You gain historical vision in a given location. Rooms, streets, tunnels, and other discrete locations accumulate psychic impressions left by powerful emotions experienced in a given area. These impressions offer you a picture of the location\'s past.</p>\n      <p>The types of events most likely to leave psychic impressions are those that elicited strong emotions: battles and betrayals, marriages and murders, births and great pain, or any other event where one emotion dominates. Everyday occurrences leave no residue for a manifester to detect.</p>\n      <p>The vision of the event is dreamlike and shadowy. You do not gain special knowledge of those involved in the vision, though you might be able to read large banners or other writing if they are in your language.</p>\n      <p>Beginning with the most recent significant event at a location and working backward in time, you can sense one distinct event for every 10 minutes you maintain concentration, if any such events exist to be sensed. Your sensitivity extends into the past a maximum number of years equal to 100 x your manifester level.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Sensitivity to Psychic Impressions\" level=\"5\"><p><h5>Sensitivity to Psychic Impressions</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Seer 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory and material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 hour<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Spread with a radius of 25 ft. + 5 ft./2 levels, centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>You gain historical vision in a given location. Rooms, streets, tunnels, and other discrete locations accumulate psychic impressions left by powerful emotions experienced in a given area. These impressions offer you a picture of the location\'s past.</p><p>The types of events most likely to leave psychic impressions are those that elicited strong emotions: battles and betrayals, marriages and murders, births and great pain, or any other event where one emotion dominates. Everyday occurrences leave no residue for a manifester to detect.</p><p>The vision of the event is dreamlike and shadowy. You do not gain special knowledge of those involved in the vision, though you might be able to read large banners or other writing if they are in your language.</p><p>Beginning with the most recent significant event at a location and working backward in time, you can sense one distinct event for every 10 minutes you maintain concentration, if any such events exist to be sensed. Your sensitivity extends into the past a maximum number of years equal to 100 x your manifester level.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (239,'Sequester, Psionic','Clairsentience',NULL,NULL,'Psion/wilder 7','None','1 standard action','Touch','One willing creature or one object (up to a 2-ft. cube/level) touched',NULL,NULL,'One day/level (D)','None or Will negates (object)','13, XP','No or Yes (object)','Subject invisible to sight and remote viewing; renders subject comatose.','75 XP.','\n      <p>As the <i>sequester</i> spell, except as noted here.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Sequester, Psionic\" level=\"5\"><p><h5>Sequester, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One willing creature or one object (up to a 2-ft. cube/level) touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No or Yes (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>13, XP<br/></td></tr></table><p>As the <i>sequester</i> spell, except as noted here.</p><p><i>XP Cost:</i> 75 XP.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (240,'Shadow Body','Psychometabolism',NULL,NULL,'Psion/wilder 8','Auditory','1 standard action','Personal','You',NULL,NULL,'1 min./level (D)',NULL,'15',NULL,'You become a living shadow (not the creature).',NULL,'\n      <p>Your body and all your equipment are subsumed by your shadow. As a living shadow, you blend perfectly into any other shadow and vanish in darkness. You appear as an unattached shadow in areas of full light.</p>\n      <p>You can move at your normal speed, on any surface, including walls and ceilings, as well as across the surfaces of liquids-even up the face of a waterfall.</p>\n      <p>Your space does not change, so you cannot move into locations you would not normally be able to move into.</p>\n      <p>While in your <i>shadow body</i>,  you gain damage reduction 10/magic and darkvision out to 60 feet. You are immune to extra damage from critical hits, ability damage, disease, drowning, and poison. You take only half damage from acid, electricity, and fire of all kinds.</p>\n      <p>While affected by this power, you can be detected by powers that read thoughts, life, or presences (including <i>true seeing</i>), or if you make suspicious movements in lighted areas.</p>\n      <p>You cannot harm anyone physically or manipulate any objects, but you can use your powers normally. Doing so may attract notice, but if you remain in a shadowed area, you get a +15 bonus on your Hide check to remain unnoticed.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Shadow Body\" level=\"5\"><p><h5>Shadow Body</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>15<br/></td></tr></table><p>Your body and all your equipment are subsumed by your shadow. As a living shadow, you blend perfectly into any other shadow and vanish in darkness. You appear as an unattached shadow in areas of full light.</p><p>You can move at your normal speed, on any surface, including walls and ceilings, as well as across the surfaces of liquids-even up the face of a waterfall.</p><p>Your space does not change, so you cannot move into locations you would not normally be able to move into.</p><p>While in your <i>shadow body</i>,  you gain damage reduction 10/magic and darkvision out to 60 feet. You are immune to extra damage from critical hits, ability damage, disease, drowning, and poison. You take only half damage from acid, electricity, and fire of all kinds.</p><p>While affected by this power, you can be detected by powers that read thoughts, life, or presences (including <i>true seeing</i>), or if you make suspicious movements in lighted areas.</p><p>You cannot harm anyone physically or manipulate any objects, but you can use your powers normally. Doing so may attract notice, but if you remain in a shadowed area, you get a +15 bonus on your Hide check to remain unnoticed.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (241,'Share Pain','Psychometabolism',NULL,NULL,'Psion/wilder 2','Material and mental','1 standard action','Touch','You and one willing creature, or two willing creatures; see text',NULL,NULL,'1 hour/level (D)',NULL,'3',NULL,'Willing subject takes some of your damage.',NULL,'\n      <p>This power creates a psychometabolic connection between you and a willing subject so that some of your wounds are transferred to the subject. You take half damage from all attacks that deal hit point damage to you, and the subject takes the remainder. The amount of damage not taken by you is taken by the subject. If your hit points are reduced by a lowered Constitution score, that reduction is not shared with the subject because it is not a form of hit point damage. When this power ends, subsequent damage is no longer divided between the subject and you, but damage already shared is not reassigned.</p>\n      <p>If you and the subject move farther away from each other than close range, the power ends.</p>\n      <p>You can manifest this power on two willing subjects, one of which you designate to share its damage with the other.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Share Pain\" level=\"5\"><p><h5>Share Pain</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material and mental<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>You and one willing creature, or two willing creatures; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>This power creates a psychometabolic connection between you and a willing subject so that some of your wounds are transferred to the subject. You take half damage from all attacks that deal hit point damage to you, and the subject takes the remainder. The amount of damage not taken by you is taken by the subject. If your hit points are reduced by a lowered Constitution score, that reduction is not shared with the subject because it is not a form of hit point damage. When this power ends, subsequent damage is no longer divided between the subject and you, but damage already shared is not reassigned.</p><p>If you and the subject move farther away from each other than close range, the power ends.</p><p>You can manifest this power on two willing subjects, one of which you designate to share its damage with the other.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (242,'Share Pain, Forced','Psychometabolism',NULL,NULL,'Psion/wilder 3','Material and mental','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 round/level (D)','Fortitude negates','5','Yes','Unwilling subject takes some of your damage.',NULL,'\n      <p>As <i>share pain</i>, except as noted here.</p>\n      <p>You attempt to force the sharing of your wounds with an unwilling creature, and for less time. If you are immune to the type of damage dealt, or if you convert lethal damage into nonlethal damage, the target takes no damage.</p>\n    ','<p><b>Augment:</b> For every 2 additional power points you spend, this power\'s save DC increases by 1.</p><p/>\n','\n      <div topic=\"Share Pain, Forced\" level=\"5\"><p><h5>Share Pain, Forced</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>As <i>share pain</i>, except as noted here.</p><p>You attempt to force the sharing of your wounds with an unwilling creature, and for less time. If you are immune to the type of damage dealt, or if you convert lethal damage into nonlethal damage, the target takes no damage.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every 2 additional power points you spend, this power\'s save DC increases by 1.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (243,'Shatter Mind Blank','Telepathy',NULL,NULL,'Psion/wilder 5','Olfactory','1 standard action','30 ft.',NULL,'30-ft. -radius burst centered on you',NULL,'Instantaneous','Will negates','9','Yes','Cancels target\'s mind blank effect.',NULL,'\n      <p>This power can negate a <i>psionic mind blank</i> or a <i>personal mind blank</i> affecting the target. If the target fails its save and does not overcome your attempt with its power resistance, you can shatter the mind blank by making a successful check (1d20 + your manifester level, maximum +20) against a DC equal to 11 + the manifester level of the creator of the <i>mind blank</i> effect. If you succeed, the <i>psionic mind blank</i> or <i>personal mind blank</i> ends, allowing you to affect the target thereafter with mind-affecting powers.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Shatter Mind Blank\" level=\"5\"><p><h5>Shatter Mind Blank</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Olfactory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>30-ft. -radius burst centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>This power can negate a <i>psionic mind blank</i> or a <i>personal mind blank</i> affecting the target. If the target fails its save and does not overcome your attempt with its power resistance, you can shatter the mind blank by making a successful check (1d20 + your manifester level, maximum +20) against a DC equal to 11 + the manifester level of the creator of the <i>mind blank</i> effect. If you succeed, the <i>psionic mind blank</i> or <i>personal mind blank</i> ends, allowing you to affect the target thereafter with mind-affecting powers.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (244,'Skate','Psychoportation',NULL,NULL,'Psion/wilder 1, psychic warrior 1','Material and visual','1 standard action','Personal or touch; see text','You or one willing creature or one unattended object (total weight up to 100 lb./level); see text',NULL,NULL,'1 min./level (D)','None','1','Yes (harmless, object)','Subject slides skillfully along the ground.',NULL,'\n      <p>You, another willing creature, or an unattended object can slide along solid ground as if on smooth ice. If you manifest <i>skate</i> on yourself or another creature, the subject of the power retains equilibrium by mental desire alone, allowing her to gracefully skate along the ground, turn, or stop suddenly as desired. The skater\'s land speed increases by 15 feet. (This adjustment is treated as an enhancement bonus.) As with any effect that increases speed, this power affects the subject\'s maximum jumping distance.</p>\n      <p>The subject can skate up or down any incline or decline she could normally walk upon without mishap, though skating up an incline reduces the subject\'s speed to normal, while skating down a decline increases her speed by an additional 15 feet. (This adjustment is treated as a circumstance bonus.)</p>\n      <p>If you manifest <i>skate</i> on an object, treat the object as having only one-tenth of its normal weight for the purpose of dragging it along the ground.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Skate\" level=\"5\"><p><h5>Skate</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 1, psychic warrior 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal or touch; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You or one willing creature or one unattended object (total weight up to 100 lb./level); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>You, another willing creature, or an unattended object can slide along solid ground as if on smooth ice. If you manifest <i>skate</i> on yourself or another creature, the subject of the power retains equilibrium by mental desire alone, allowing her to gracefully skate along the ground, turn, or stop suddenly as desired. The skater\'s land speed increases by 15 feet. (This adjustment is treated as an enhancement bonus.) As with any effect that increases speed, this power affects the subject\'s maximum jumping distance.</p><p>The subject can skate up or down any incline or decline she could normally walk upon without mishap, though skating up an incline reduces the subject\'s speed to normal, while skating down a decline increases her speed by an additional 15 feet. (This adjustment is treated as a circumstance bonus.)</p><p>If you manifest <i>skate</i> on an object, treat the object as having only one-tenth of its normal weight for the purpose of dragging it along the ground.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (245,'Solicit Psicrystal','Telepathy',NULL,NULL,'Psion/wilder 3','Auditory','1 swift action','Close (25 ft. + 5 ft./2 levels)','Your psicrystal',NULL,NULL,'1 round/level (D)','No','5','No','Your psicrystal takes over your concentration power.',NULL,'\n      <p>Your psicrystal takes over the responsibility of maintaining concentration on any single power you have manifested and are concentrating on. While maintaining this concentration, the psicrystal is limited to move actions in each round, as normal. When the duration of <i>solicit psicrystal</i> expires, the power you transferred to the psicrystal ends (even if this would mean that the power ends earlier than normal). If necessary, the psicrystal makes Concentration checks using your Concentration modifier.</p>\n      <p>You can manifest this power (and transfer the responsibility) with an instant thought, quickly enough to gain the benefit of the power before you take any other actions in a round. Manifesting the power is a swift action, like manifesting a quickened power, and it counts toward the normal limit of one quickened power per round. You cannot manifest this power when it isn\'t your turn.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s maximum duration increases by 1 round.</p><p/>\n','\n      <div topic=\"Solicit Psicrystal\" level=\"5\"><p><h5>Solicit Psicrystal</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 swift action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Your psicrystal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>Your psicrystal takes over the responsibility of maintaining concentration on any single power you have manifested and are concentrating on. While maintaining this concentration, the psicrystal is limited to move actions in each round, as normal. When the duration of <i>solicit psicrystal</i> expires, the power you transferred to the psicrystal ends (even if this would mean that the power ends earlier than normal). If necessary, the psicrystal makes Concentration checks using your Concentration modifier.</p><p>You can manifest this power (and transfer the responsibility) with an instant thought, quickly enough to gain the benefit of the power before you take any other actions in a round. Manifesting the power is a swift action, like manifesting a quickened power, and it counts toward the normal limit of one quickened power per round. You cannot manifest this power when it isn\'t your turn.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s maximum duration increases by 1 round.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (246,'Steadfast Perception','Clairsentience',NULL,NULL,'Psychic warrior 4','Visual','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)',NULL,'7',NULL,'Gain immunity to illusory effects, +6 bonus on Spot and Search checks.',NULL,'\n      <p>Your vision cannot be distracted or misled, granting you immunity to all figments and glamers (such as <i>invisibility</i>). Moreover, your Spot and Search checks receive a +6 enhancement bonus for the duration of this power. This power also grants you another saving throw against someone using <i>false sensory input</i> on you, but you must realize that that power has been used in order to know enough to manifest <i>steadfast perception</i>.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Steadfast Perception\" level=\"5\"><p><h5>Steadfast Perception</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>Your vision cannot be distracted or misled, granting you immunity to all figments and glamers (such as <i>invisibility</i>). Moreover, your Spot and Search checks receive a +6 enhancement bonus for the duration of this power. This power also grants you another saving throw against someone using <i>false sensory input</i> on you, but you must realize that that power has been used in order to know enough to manifest <i>steadfast perception</i>.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (247,'Stomp','Psychokinesis',NULL,NULL,'Psychic warrior 1','Auditory and visual','1 standard action','20 ft.',NULL,'Cone-shaped spread',NULL,'Instantaneous','Reflex negates','1','No','Subjects fall prone and take 1d4 nonlethal damage.',NULL,'\n      <p>Your foot stomp precipitates a psychokinetic shock wave that travels along the ground, toppling creatures and loose objects. The shock wave affects only creatures standing on the ground within the power\'s area. Creatures that fail their saves are thrown to the ground, become prone, and take 1d4 points of nonlethal damage.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s nonlethal damage increases by 1d4 points.</p><p/>\n','\n      <div topic=\"Stomp\" level=\"5\"><p><h5>Stomp</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>Your foot stomp precipitates a psychokinetic shock wave that travels along the ground, toppling creatures and loose objects. The shock wave affects only creatures standing on the ground within the power\'s area. Creatures that fail their saves are thrown to the ground, become prone, and take 1d4 points of nonlethal damage.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s nonlethal damage increases by 1d4 points.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (248,'Strength of My Enemy','Psychometabolism',NULL,NULL,'Psychic warrior 2','Visual; see text','1 standard action','Personal','You',NULL,NULL,'1 round/level (D)',NULL,'3',NULL,'Siphon away your enemy\'s strength and grow stronger.',NULL,'\n      <p>You gain the ability to siphon away your enemy\'s strength for your own use. One of your natural or manufactured weapons becomes the instrument of your desire, and deals 1 point of Strength damage on each successful hit. You gain that point of Strength as an enhancement bonus to your Strength score. Strength you siphon from different foes is tracked separately-the total siphoned from each individual foe is considered a separate enhancement bonus to your Strength (maximum +8), and you gain only the highest total.</p>\n    ','<p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. For every 3 additional power points you spend, the maximum enhancement bonus you can add to your Strength increases by 2.</p><p>2. If you spend 6 additional power points, you can manifest this power as a swift action.</p><p/>\n','\n      <div topic=\"Strength of My Enemy\" level=\"5\"><p><h5>Strength of My Enemy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>You gain the ability to siphon away your enemy\'s strength for your own use. One of your natural or manufactured weapons becomes the instrument of your desire, and deals 1 point of Strength damage on each successful hit. You gain that point of Strength as an enhancement bonus to your Strength score. Strength you siphon from different foes is tracked separately-the total siphoned from each individual foe is considered a separate enhancement bonus to your Strength (maximum +8), and you gain only the highest total.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. For every 3 additional power points you spend, the maximum enhancement bonus you can add to your Strength increases by 2.</p><p>2. If you spend 6 additional power points, you can manifest this power as a swift action.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (249,'Suggestion, Psionic','Telepathy','Compulsion','Mind-Affecting, Language-Dependent','Telepath 2','Auditory','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 hour/level or until completed','Will negates','3','Yes','Compels subject to follow stated course of action.',NULL,'\n      <p>As the <i>suggestion</i> spell, except as noted here.</p>\n    ','<p><b>Augment:</b> For every 2 additional power points you spend, this power can affect an additional target. Any additional target cannot be more than 15 feet from another target of the power.</p><p/>\n','\n      <div topic=\"Suggestion, Psionic\" level=\"5\"><p><h5>Suggestion, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy (Compulsion) [Mind-Affecting, Language-Dependent]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Telepath 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level or until completed<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>As the <i>suggestion</i> spell, except as noted here.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every 2 additional power points you spend, this power can affect an additional target. Any additional target cannot be more than 15 feet from another target of the power.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (250,'Suspend Life','Psychometabolism',NULL,NULL,'Psion/wilder 6, psychic warrior 6','Olfactory','1 standard action','Personal','You',NULL,NULL,'Permanent unless ended or dismissed; see text',NULL,'11',NULL,'Put yourself into a state akin to suspended animation.',NULL,'\n      <p>You can place yourself into a trance so deep that you are almost in suspended animation. Even powers that detect life or thought are incapable of determining that you are alive.</p>\n      <p>While you are suspended, you are aware of your surroundings. You feel the passage of one day for every year that actually passes. Though on a slower schedule, you grow hungry after a \'day\' without food (though a year passes in actuality) and begin to suffer the effects of thirst and starvation as appropriate.</p>\n      <p>If you take any damage, you come out of your trance 4 rounds later. The trance can also be ended by a successful use of <i>dispel psionics</i>. If you choose to dismiss the power, your trance ends 10 rounds later.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Suspend Life\" level=\"5\"><p><h5>Suspend Life</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 6, psychic warrior 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Olfactory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent unless ended or dismissed; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>11<br/></td></tr></table><p>You can place yourself into a trance so deep that you are almost in suspended animation. Even powers that detect life or thought are incapable of determining that you are alive.</p><p>While you are suspended, you are aware of your surroundings. You feel the passage of one day for every year that actually passes. Though on a slower schedule, you grow hungry after a \'day\' without food (though a year passes in actuality) and begin to suffer the effects of thirst and starvation as appropriate.</p><p>If you take any damage, you come out of your trance 4 rounds later. The trance can also be ended by a successful use of <i>dispel psionics</i>. If you choose to dismiss the power, your trance ends 10 rounds later.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (251,'Sustenance','Psychometabolism',NULL,NULL,'Psion/wilder 2, psychic warrior 2','Material','1 standard action','Personal','You',NULL,NULL,'Instantaneous',NULL,'3',NULL,'You can go without food and water for one day.',NULL,'\n      <p>You can go without food and water for one day. Each time you manifest this power, your body manufactures suffi- cient solid and liquid nourishment to satisfy your needs for that time.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Sustenance\" level=\"5\"><p><h5>Sustenance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2, psychic warrior 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>You can go without food and water for one day. Each time you manifest this power, your body manufactures suffi- cient solid and liquid nourishment to satisfy your needs for that time.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (252,'Swarm of Crystals','Metacreativity','Creation',NULL,'Psion/wilder 2','Material','1 standard action','15 ft.',NULL,'Cone-shaped spread',NULL,'Instantaneous','None','3','No','Crystal shards are sprayed forth doing 3d4 slashing damage.',NULL,'\n      <p>Thousands of tiny crystal shards spray forth in an arc from your hand. These razorlike crystals slice everything in their path. Anyone caught in the cone takes 3d4 points of slashing damage.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d4 points.</p><p/>\n','\n      <div topic=\"Swarm of Crystals\" level=\"5\"><p><h5>Swarm of Crystals</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Metacreativity (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>15 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>Thousands of tiny crystal shards spray forth in an arc from your hand. These razorlike crystals slice everything in their path. Anyone caught in the cone takes 3d4 points of slashing damage.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d4 points.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (253,'Synesthete','Psychometabolism',NULL,NULL,'Psion/wilder 1, psychic warrior 1','Material','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)',NULL,'1',NULL,'You receive one kind of sense when another sense is stimulated.',NULL,'\n      <p>You receive one kind of sensory input when a different sense is stimulated. In particular, you can either feel light or feel sound. You can shift your stimulated sense between these two options once per round as a swift action. Your senses continue to work normally as well, unless they are impaired for some reason.</p>\n      <p>Your face must be uncovered to use this power, because it is the skin of your face that acts as the sensory receiver.</p>\n      <p>If you are feeling light by absorbing ambient light onto your skin, you have your normal visual abilities (except for darkvision), even if your eyes are closed or you are blinded. If your eyes are working normally, you gain a +4 circumstance bonus on all Spot and Search checks. While feeling light, you are immune to gaze attacks.</p>\n      <p>If you are feeling sound by absorbing sound onto your skin and your ears are working normally, the expanded audio input provides you with a +4 circumstance bonus on Listen checks.</p>\n      <p>Psionic or magical displacement effects, invisibility effects, illusions, and other similar effects confuse your <i>synesthete</i> senses just as they would your normal senses.</p>\n      <p>You can also use this power to see sound if you are deafened, or hear light if you are blinded, thus removing all penalties associated with either condition (though you gain no bonuses for using the power in this way if you are not deafened or blinded).</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Synesthete\" level=\"5\"><p><h5>Synesthete</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 1, psychic warrior 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>You receive one kind of sensory input when a different sense is stimulated. In particular, you can either feel light or feel sound. You can shift your stimulated sense between these two options once per round as a swift action. Your senses continue to work normally as well, unless they are impaired for some reason.</p><p>Your face must be uncovered to use this power, because it is the skin of your face that acts as the sensory receiver.</p><p>If you are feeling light by absorbing ambient light onto your skin, you have your normal visual abilities (except for darkvision), even if your eyes are closed or you are blinded. If your eyes are working normally, you gain a +4 circumstance bonus on all Spot and Search checks. While feeling light, you are immune to gaze attacks.</p><p>If you are feeling sound by absorbing sound onto your skin and your ears are working normally, the expanded audio input provides you with a +4 circumstance bonus on Listen checks.</p><p>Psionic or magical displacement effects, invisibility effects, illusions, and other similar effects confuse your <i>synesthete</i> senses just as they would your normal senses.</p><p>You can also use this power to see sound if you are deafened, or hear light if you are blinded, thus removing all penalties associated with either condition (though you gain no bonuses for using the power in this way if you are not deafened or blinded).</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (254,'Telekinetic Force','Psychokinesis',NULL,'Force','Psion/wilder 3','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One object at a time',NULL,NULL,'Concentration, up to 1 round/level','Will negates (object); see text','5','Yes (object)','Move an object with the sustained force of your mind.',NULL,'\n      <p>You move an object by concentrating your mind upon its current location and then the location you desire, creating a sustained force. You can move an object weighing no more than 250 pounds up to 20 feet per round. A creature can negate the effect on an object it possesses with a successful Will save or with power resistance. The weight can be moved across the ground or through the air. This power ends if the object is forced out of range. If you cease concentration, the object falls or stops.</p>\n      <p>You can drop a weight and pick up another during the power\'s duration, as long as you don\'t stop concentrating on maintaining the power. An object can be telekinetically manipulated as if you were moving it with one hand.</p>\n      <p>If you spend at least 5 rounds concentrating on an unattended object, you can attempt to break or burst it as if making a Strength check, except that you apply your key ability modifier to the check instead of your Strength modifier.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, the weight limit of the target increases by 25 pounds.</p><p/>\n','\n      <div topic=\"Telekinetic Force\" level=\"5\"><p><h5>Telekinetic Force</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One object at a time<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>You move an object by concentrating your mind upon its current location and then the location you desire, creating a sustained force. You can move an object weighing no more than 250 pounds up to 20 feet per round. A creature can negate the effect on an object it possesses with a successful Will save or with power resistance. The weight can be moved across the ground or through the air. This power ends if the object is forced out of range. If you cease concentration, the object falls or stops.</p><p>You can drop a weight and pick up another during the power\'s duration, as long as you don\'t stop concentrating on maintaining the power. An object can be telekinetically manipulated as if you were moving it with one hand.</p><p>If you spend at least 5 rounds concentrating on an unattended object, you can attempt to break or burst it as if making a Strength check, except that you apply your key ability modifier to the check instead of your Strength modifier.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, the weight limit of the target increases by 25 pounds.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (255,'Telekinetic Maneuver','Psychokinesis',NULL,'Force','Psion/wilder 4','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'Concentration, up to 1 round/level','None','7','Yes','Telekinetically bull rush, disarm, grapple, or trip your target.',NULL,'\n      <p>You can affect a foe by concentrating your mind upon its current status and the status you desire, once per round. You can perform a bull rush, a disarm, a grapple (including a pin), or a trip. Resolve these attempts as normal, except that they don\'t provoke attacks of opportunity, you use your manifester level in place of your base attack bonus (for disarm and grapple attempts), you use your Intelligence modifier in place of your Strength modifier or Dexterity modifier, and a failed attempt doesn\'t allow a reactive attempt by the target (such as normally allowed on disarm or trip attempts). No save is allowed against these attempts, but power resistance applies normally.</p>\n    ','<p><b>Augment:</b> For every 2 additional power points you spend, this power grants a +1 bonus on your checks involving bull rush, disarm, grapple, or trip attempts.</p><p/>\n','\n      <div topic=\"Telekinetic Maneuver\" level=\"5\"><p><h5>Telekinetic Maneuver</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>You can affect a foe by concentrating your mind upon its current status and the status you desire, once per round. You can perform a bull rush, a disarm, a grapple (including a pin), or a trip. Resolve these attempts as normal, except that they don\'t provoke attacks of opportunity, you use your manifester level in place of your base attack bonus (for disarm and grapple attempts), you use your Intelligence modifier in place of your Strength modifier or Dexterity modifier, and a failed attempt doesn\'t allow a reactive attempt by the target (such as normally allowed on disarm or trip attempts). No save is allowed against these attempts, but power resistance applies normally.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every 2 additional power points you spend, this power grants a +1 bonus on your checks involving bull rush, disarm, grapple, or trip attempts.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (256,'Telekinetic Sphere, Psionic','Psychokinesis',NULL,'Force','Kineticist 8','Material','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'1-ft. -diameter/level sphere, centered around creatures or objects','1 min./level (D)','Reflex negates (object)','15','Yes (object)',NULL,NULL,'\n      <p>As the <i>telekinetic sphere</i> spell, except as noted here.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Telekinetic Sphere, Psionic\" level=\"5\"><p><h5>Telekinetic Sphere, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Kineticist 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>1-ft. -diameter/level sphere, centered around creatures or objects<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>15<br/></td></tr></table><p>As the <i>telekinetic sphere</i> spell, except as noted here.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (257,'Telekinetic Thrust','Psychokinesis',NULL,NULL,'Psion/wilder 3','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One or more objects or creatures with a total weight of 250 lb. or less',NULL,NULL,'Instantaneous','Will negates or Will negates (object); see text','5','Yes or Yes (object); see text','Hurl objects with the force of your mind.',NULL,'\n      <p>You can affect one or more objects or creatures by concentrating your mind upon, sending them in a deadly hail at your foes-or simply by hurling your foe! You can hurl one object or creature per manifester level (maximum fifteen separate targets), as long as all are within the power\'s range and each is no more than 10 feet away from another one. Each object or creature can be hurled a maximum distance of 10 feet per level.</p>\n      <p>You must succeed on ranged attack rolls (one per creature or object thrown) to hit the target of the hurled items with the items, applying your Intelligence modifier to the attack roll instead of your Dexterity modifier. Hurled weapons deal their standard damage (your Strength bonus does not apply; arrows or bolts deal damage as daggers of their size when used in this manner). Other objects deal damage ranging from 1 point per 25 pounds of weight (for less dangerous objects such as an empty barrel) to 1d6 points per 25 pounds of weight (for hard, dense objects such as a boulder).</p>\n      <p>Creatures are allowed Will saves (and power resistance) to negate the effect, as are those whose held possessions are targeted by this power.</p>\n      <p>If you use this power to hurl a creature against a solid surface, it takes damage as if it had fallen 10 feet (1d6 points).</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, the weight limit of the target or targets increases by 25 pounds.</p><p/>\n','\n      <div topic=\"Telekinetic Thrust\" level=\"5\"><p><h5>Telekinetic Thrust</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target or Targets:</b><br/></td><td>One or more objects or creatures with a total weight of 250 lb. or less<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates or Will negates (object); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes or Yes (object); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>You can affect one or more objects or creatures by concentrating your mind upon, sending them in a deadly hail at your foes-or simply by hurling your foe! You can hurl one object or creature per manifester level (maximum fifteen separate targets), as long as all are within the power\'s range and each is no more than 10 feet away from another one. Each object or creature can be hurled a maximum distance of 10 feet per level.</p><p>You must succeed on ranged attack rolls (one per creature or object thrown) to hit the target of the hurled items with the items, applying your Intelligence modifier to the attack roll instead of your Dexterity modifier. Hurled weapons deal their standard damage (your Strength bonus does not apply; arrows or bolts deal damage as daggers of their size when used in this manner). Other objects deal damage ranging from 1 point per 25 pounds of weight (for less dangerous objects such as an empty barrel) to 1d6 points per 25 pounds of weight (for hard, dense objects such as a boulder).</p><p>Creatures are allowed Will saves (and power resistance) to negate the effect, as are those whose held possessions are targeted by this power.</p><p>If you use this power to hurl a creature against a solid surface, it takes damage as if it had fallen 10 feet (1d6 points).</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, the weight limit of the target or targets increases by 25 pounds.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (258,'Telempathic Projection','Telepathy','Charm','Mind-Affecting','Psion/wilder 1','Visual','1 standard action','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'1 min./level','Will negates','1','Yes','Alter the subject\'s mood.',NULL,'\n      <p>You alter the subject\'s mood, adjusting its attitude toward you by one step in a positive direction. For instance, an unfriendly creature can be made indifferent, or a hostile creature unfriendly. You can grant a +4 bonus on your own (or others\') Bluff, Diplomacy, Intimidate, Perform, or Sense Motive checks involving the affected creature.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Telempathic Projection\" level=\"5\"><p><h5>Telempathic Projection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy (Charm) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>You alter the subject\'s mood, adjusting its attitude toward you by one step in a positive direction. For instance, an unfriendly creature can be made indifferent, or a hostile creature unfriendly. You can grant a +4 bonus on your own (or others\') Bluff, Diplomacy, Intimidate, Perform, or Sense Motive checks involving the affected creature.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (259,'Teleport, Psionic','Psychoportation','Teleportation',NULL,'Nomad 5','Visual','1 standard action','Personal and touch','You and touched objects or other touched willing creatures',NULL,NULL,'Instantaneous','None or Will negates (object)','9','No or Yes (object)','Instantly transports you as far as 100 miles/level.',NULL,'\n      <p>As the <i>teleport</i> spell, except as noted here.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Teleport, Psionic\" level=\"5\"><p><h5>Teleport, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Nomad 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal and touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target or Targets:</b><br/></td><td>You and touched objects or other touched willing creatures<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No or Yes (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>As the <i>teleport</i> spell, except as noted here.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (260,'Teleport, Psionic Greater','Psychoportation','Teleportation',NULL,'Psion/wilder 8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'15',NULL,'As psionic teleport, but no range limit and no off-target arrival.',NULL,'\n      <p>As the <i>greater teleport</i> spell, except as noted here.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Teleport, Psionic Greater\" level=\"5\"><p><h5>Teleport, Psionic Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>15<br/></td></tr></table><p>As the <i>greater teleport</i> spell, except as noted here.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (261,'Teleportation Circle, Psionic','Psychoportation','Teleportation',NULL,'Nomad 9','Mental','10 minutes','0 ft.',NULL,NULL,'5-ft. -radius circle that teleports those who activate it','10 min./level (D)','None','17','Yes',NULL,NULL,'\n      <p>As the <i>teleportation circle</i> spell, except as noted here.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Teleportation Circle, Psionic\" level=\"5\"><p><h5>Teleportation Circle, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Nomad 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Mental<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>5-ft. -radius circle that teleports those who activate it<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>17<br/></td></tr></table><p>As the <i>teleportation circle</i> spell, except as noted here.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (262,'Teleport Trigger','Psychoportation','Teleportation',NULL,'Nomad 5','Material','1 standard action','Personal','You',NULL,NULL,'1 hour/level (D)',NULL,'9',NULL,'Predetermined event triggers teleport.6Banishment, Psionic: Banishes extraplanar creatures.7Dream Travel: Travel to other places through dreams.',NULL,'\n      <p>You specify a situation that triggers your automatic manifestation of a <i>psionic teleport</i>,  taking you to a predetermined location. You must know the <i>psionic teleport</i> power and have sufficient power points to manifest it when the specified situation occurs.</p>\n      <p>The <i>teleport trigger</i> goes off on the initiative count immediately after the specified situation occurs, even if you are flat-footed or you have already taken your turn in the current round. The specified situation can be described in general terms or specific terms.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Teleport Trigger\" level=\"5\"><p><h5>Teleport Trigger</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Nomad 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>You specify a situation that triggers your automatic manifestation of a <i>psionic teleport</i>,  taking you to a predetermined location. You must know the <i>psionic teleport</i> power and have sufficient power points to manifest it when the specified situation occurs.</p><p>The <i>teleport trigger</i> goes off on the initiative count immediately after the specified situation occurs, even if you are flat-footed or you have already taken your turn in the current round. The specified situation can be described in general terms or specific terms.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (263,'Temporal Acceleration','Psychoportation',NULL,NULL,'Psion/wilder 6','None','1 swift action','Personal','You',NULL,NULL,'1 round (in apparent time); see text',NULL,'11',NULL,'Your time frame accelerates for 1 round.',NULL,'\n      <p>You enter another time frame, speeding up so greatly that all other creatures seem frozen, though they are actually still moving at normal speed. You are free to act for 1 round of apparent time. You can manifest powers, cast spells, move, or perform other types of actions, subject to the restrictions outlined below.</p>\n      <p>While your <i>temporal acceleration</i> is in effect, other creatures are invulnerable to your attacks and powers. This means you cannot target a creature with any attack or power. However, a power you manifest that affects an area and has a duration longer than the remaining duration of your <i>temporal acceleration</i> has its normal effect on creatures in the area once this power ends.</p>\n      <p>You can affect an unattended object but not an object held, carried, or worn by another creature. You are undetectable by any means while your <i>temporal acceleration</i> lasts.</p>\n      <p>While under the effect of this power, you cannot enter an area protected by a <i>null psionics field</i> or by a power or spell that neutralizes high-level powers or spells. Normal and magical fire, cold, acid, and the like can still harm you.</p>\n      <p>When your <i>temporal acceleration</i> expires, you resume acting during your current turn in the standard time frame. You are shaken for 1 round upon your return to the standard time frame.</p>\n      <p>Splintered or partitioned minds within your own mind, such as might be in effect through the use of powers such as <i>schism</i>, are not temporally speeded up, even if your second mind manifested this power (your primary mind gains the benefit, while your second mind remains stuck in the standard time frame).</p>\n      <p>Manifesting this power is a swift action, like manifesting a quickened power, and it counts toward the normal limit of one quickened power per round. You cannot manifest this power when it isn\'t your turn.</p>\n    ','<p><b>Augment:</b> For every 4 additional power points you spend, this power\'s duration (in apparent time) increases by 1 round.</p><p/>\n','\n      <div topic=\"Temporal Acceleration\" level=\"5\"><p><h5>Temporal Acceleration</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 swift action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round (in apparent time); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>11<br/></td></tr></table><p>You enter another time frame, speeding up so greatly that all other creatures seem frozen, though they are actually still moving at normal speed. You are free to act for 1 round of apparent time. You can manifest powers, cast spells, move, or perform other types of actions, subject to the restrictions outlined below.</p><p>While your <i>temporal acceleration</i> is in effect, other creatures are invulnerable to your attacks and powers. This means you cannot target a creature with any attack or power. However, a power you manifest that affects an area and has a duration longer than the remaining duration of your <i>temporal acceleration</i> has its normal effect on creatures in the area once this power ends.</p><p>You can affect an unattended object but not an object held, carried, or worn by another creature. You are undetectable by any means while your <i>temporal acceleration</i> lasts.</p><p>While under the effect of this power, you cannot enter an area protected by a <i>null psionics field</i> or by a power or spell that neutralizes high-level powers or spells. Normal and magical fire, cold, acid, and the like can still harm you.</p><p>When your <i>temporal acceleration</i> expires, you resume acting during your current turn in the standard time frame. You are shaken for 1 round upon your return to the standard time frame.</p><p>Splintered or partitioned minds within your own mind, such as might be in effect through the use of powers such as <i>schism</i>, are not temporally speeded up, even if your second mind manifested this power (your primary mind gains the benefit, while your second mind remains stuck in the standard time frame).</p><p>Manifesting this power is a swift action, like manifesting a quickened power, and it counts toward the normal limit of one quickened power per round. You cannot manifest this power when it isn\'t your turn.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every 4 additional power points you spend, this power\'s duration (in apparent time) increases by 1 round.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (264,'Thicken Skin','Psychometabolism',NULL,NULL,'Egoist 1, psychic warrior 1','Material and olfactory','1 standard action','Personal','You',NULL,NULL,'10 min./level',NULL,'1',NULL,'Gain +1 enhancement bonus to your AC for 10 min./level.',NULL,'\n      <p>Your skin or natural armor thickens and spreads across your body, providing a +1 enhancement bonus to your Armor Class.</p>\n    ','<p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. For every 3 additional power points you spend, the enhancement bonus increases by 1.</p><p>2. If you spend 6 additional power points, you can manifest this power as a swift action.</p><p/>\n','\n      <div topic=\"Thicken Skin\" level=\"5\"><p><h5>Thicken Skin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Egoist 1, psychic warrior 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material and olfactory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>Your skin or natural armor thickens and spreads across your body, providing a +1 enhancement bonus to your Armor Class.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. For every 3 additional power points you spend, the enhancement bonus increases by 1.</p><p>2. If you spend 6 additional power points, you can manifest this power as a swift action.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (265,'Thought Shield','Telepathy',NULL,'Mind-Affecting','Psion/wilder 2, psychic warrior 2','Auditory','1 immediate action','Personal','You',NULL,NULL,'1 round',NULL,'3',NULL,'Gain PR 13 against mind-affecting powers.',NULL,'\n      <p>You fortify your mind against intrusions, gaining power resistance 13 against all mind-affecting powers.</p>\n      <p>You can manifest this power instantly, quickly enough to gain its benefits in an emergency. Manifesting the power is an immediate action. You can use this power even when it\'s not your turn.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s duration increases by 1 round, and the power resistance it provides increases by 1 point.</p><p/>\n','\n      <div topic=\"Thought Shield\" level=\"5\"><p><h5>Thought Shield</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2, psychic warrior 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 immediate action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>You fortify your mind against intrusions, gaining power resistance 13 against all mind-affecting powers.</p><p>You can manifest this power instantly, quickly enough to gain its benefits in an emergency. Manifesting the power is an immediate action. You can use this power even when it\'s not your turn.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s duration increases by 1 round, and the power resistance it provides increases by 1 point.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (266,'Time Hop','Psychoportation',NULL,NULL,'Psion/wilder 3','Auditory and visual','1 standard action','Close (25 ft. + 5 ft./2 levels)','One Medium or smaller creature, or one object weighing 300 lb. or less',NULL,NULL,'1 round/level; see text','Will negates','5','Yes','Subject hops forward in time 1 round/level.',NULL,'\n      <p>The subject of the power hops forward in time 1 round for every manifester level you have. In effect, the subject seems to disappear in a shimmer of silver energy, then reappear after the duration of this power expires. The subject reappears in exactly the same orientation and condition as before. From the subject\'s point of view, no time has passed at all.</p>\n      <p>In each round of the power\'s duration, on what would have been the subject\'s turn, it can attempt a DC 15 Wisdom check. Success allows the subject to return. The subject can act normally on its next turn after this power ends.</p>\n      <p>If the space from which the subject departed is occupied upon his return to the time stream, he appears in the closest unoccupied space, still in his original orientation. Determine the closest space randomly if necessary.</p>\n    ','<p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. For every 2 additional power points you spend, you can affect a creature of one size category larger, or double the weight of an object to be affected.</p><p>2. For every 2 additional power points you spend, this power can affect an additional target. Any additional target cannot be more than 15 feet from another target of the power.</p><p/>\n','\n      <div topic=\"Time Hop\" level=\"5\"><p><h5>Time Hop</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One Medium or smaller creature, or one object weighing 300 lb. or less<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>The subject of the power hops forward in time 1 round for every manifester level you have. In effect, the subject seems to disappear in a shimmer of silver energy, then reappear after the duration of this power expires. The subject reappears in exactly the same orientation and condition as before. From the subject\'s point of view, no time has passed at all.</p><p>In each round of the power\'s duration, on what would have been the subject\'s turn, it can attempt a DC 15 Wisdom check. Success allows the subject to return. The subject can act normally on its next turn after this power ends.</p><p>If the space from which the subject departed is occupied upon his return to the time stream, he appears in the closest unoccupied space, still in his original orientation. Determine the closest space randomly if necessary.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> You can augment this power in one or both of the following ways.</p><p>1. For every 2 additional power points you spend, you can affect a creature of one size category larger, or double the weight of an object to be affected.</p><p>2. For every 2 additional power points you spend, this power can affect an additional target. Any additional target cannot be more than 15 feet from another target of the power.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (267,'Time Hop, Mass','Psychoportation',NULL,NULL,'Nomad 8','Auditory and visual','1 standard action','Close (25 ft. + 5 ft./2 levels)','All willing creatures in range',NULL,NULL,'Up to 1 hour/level; see text','Will negates','15','Yes','Subject hops forward in time 1 round/level.',NULL,'\n      <p>As <i>time hop</i>, except you can affect any number of willing subjects in range, including yourself. You can choose which creatures are affected by the power. The subjects hop forward in time a number of hours equal to your manifester level, or some shorter number of hours; you decide how many hours the <i>mass time hop</i> lasts when you manifest the power.</p>\n    ','<p><b>Augment:</b> If you spend 6 additional power points, you can manifest this power as an immediate action.</p><p/>\n','\n      <div topic=\"Time Hop, Mass\" level=\"5\"><p><h5>Time Hop, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Nomad 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>All willing creatures in range<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Up to 1 hour/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>15<br/></td></tr></table><p>As <i>time hop</i>, except you can affect any number of willing subjects in range, including yourself. You can choose which creatures are affected by the power. The subjects hop forward in time a number of hours equal to your manifester level, or some shorter number of hours; you decide how many hours the <i>mass time hop</i> lasts when you manifest the power.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> If you spend 6 additional power points, you can manifest this power as an immediate action.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (268,'Time Regression','Psychoportation',NULL,NULL,'Nomad 9','None','1 standard action','Personal','You',NULL,NULL,'Instantaneous',NULL,'17, XP',NULL,NULL,'1,000 XP.','\n      <p>You can regress apparent time 1 round into the past. In effect, you \'replay\' the previous round of activity. The power regresses time to the point along the time stream just prior to your previous turn, undoing the effects of everyone else\'s actions in the meantime. Once you have used <i>time regression</i>,  only you retain knowledge of what happened during the round that is being replayed; however, you can communicate that knowledge verbally to your companions, if desired. During the round that you live through a second time, you can act on knowledge you previously gained by already living through the immediate future. In all likelihood, you\'ll probably not choose to manifest <i>time regression</i> during your second pass through the time stream, instead taking completely new actions, but you pay the XP cost all the same.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Time Regression\" level=\"5\"><p><h5>Time Regression</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Nomad 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>17, XP<br/></td></tr></table><p>You can regress apparent time 1 round into the past. In effect, you \'replay\' the previous round of activity. The power regresses time to the point along the time stream just prior to your previous turn, undoing the effects of everyone else\'s actions in the meantime. Once you have used <i>time regression</i>,  only you retain knowledge of what happened during the round that is being replayed; however, you can communicate that knowledge verbally to your companions, if desired. During the round that you live through a second time, you can act on knowledge you previously gained by already living through the immediate future. In all likelihood, you\'ll probably not choose to manifest <i>time regression</i> during your second pass through the time stream, instead taking completely new actions, but you pay the XP cost all the same.</p><p><i>XP Cost:</i> 1,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (269,'Timeless Body','Psychoportation',NULL,NULL,'Psion/wilder 9','Material','1 standard action','Personal','You',NULL,NULL,'1 round',NULL,'17',NULL,'Ignore all harmful, and helpful, effects for 1 round.',NULL,'\n      <p>Your body ignores all harmful (and helpful) effects, beginning when you finish manifesting this power and ending at the end of your next turn. While <i>timeless body</i> is in effect, you are invulnerable to all attacks and powers.</p>\n      <p>This power cannot be quickened.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Timeless Body\" level=\"5\"><p><h5>Timeless Body</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>17<br/></td></tr></table><p>Your body ignores all harmful (and helpful) effects, beginning when you finish manifesting this power and ending at the end of your next turn. While <i>timeless body</i> is in effect, you are invulnerable to all attacks and powers.</p><p>This power cannot be quickened.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (270,'Tongues, Psionic','Telepathy',NULL,'Mind-Affecting','Psion/wilder 2','None','1 standard action','Personal','You',NULL,NULL,'10 min./level',NULL,'3',NULL,'You can communicate with intelligent creatures.',NULL,'\n      <p>As the <i>tongues</i> spell, except as noted here. This power does not enable you to speak with creatures immune to mind-affecting powers.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Tongues, Psionic\" level=\"5\"><p><h5>Tongues, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>As the <i>tongues</i> spell, except as noted here. This power does not enable you to speak with creatures immune to mind-affecting powers.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (271,'Tornado Blast','Psychokinesis',NULL,NULL,'Kineticist 9','Auditory and visual; see text','1 round','Long (400 ft. + 40 ft./level)',NULL,'40-ft. -radius spread',NULL,'Instantaneous','Reflex half; see text','17','No',NULL,NULL,'\n      <p>You induce the formation of a slender vortex of fiercely swirling air. When you manifest it, a vortex of air visibly and audibly snakes out from your outstretched hand.</p>\n      <p>If you want to aim the vortex at a specific creature, you can make a ranged touch attack to strike the creature. If you succeed, direct contact with the vortex deals 8d6 points of damage to the creature (no save).</p>\n      <p>Regardless of whether your ranged touch attack hits (and even if you forgo the attack), all creatures in the area (including the one possibly damaged by direct contact) are picked up and violently dashed about, dealing 17d6 points of damage to each one. Creatures that make a successful Reflex save take half damage.</p>\n      <p>After being dashed about, each creature that was affected finds itself situated in a new space 1d4 x 10 feet away from its original space in a random direction. Walls and other barriers can restrict this relocation; in such a case, the creature ends up adjacent to the barrier.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s area damage (not the damage from direct contact dealt to a specific creature) increases by 1d6 points (to a maximum of 24d6 points). For each extra 2d6 points of damage, this power\'s save DC increases by 1.</p><p/>\n','\n      <div topic=\"Tornado Blast\" level=\"5\"><p><h5>Tornado Blast</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Kineticist 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory and visual; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>17<br/></td></tr></table><p>You induce the formation of a slender vortex of fiercely swirling air. When you manifest it, a vortex of air visibly and audibly snakes out from your outstretched hand.</p><p>If you want to aim the vortex at a specific creature, you can make a ranged touch attack to strike the creature. If you succeed, direct contact with the vortex deals 8d6 points of damage to the creature (no save).</p><p>Regardless of whether your ranged touch attack hits (and even if you forgo the attack), all creatures in the area (including the one possibly damaged by direct contact) are picked up and violently dashed about, dealing 17d6 points of damage to each one. Creatures that make a successful Reflex save take half damage.</p><p>After being dashed about, each creature that was affected finds itself situated in a new space 1d4 x 10 feet away from its original space in a random direction. Walls and other barriers can restrict this relocation; in such a case, the creature ends up adjacent to the barrier.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s area damage (not the damage from direct contact dealt to a specific creature) increases by 1d6 points (to a maximum of 24d6 points). For each extra 2d6 points of damage, this power\'s save DC increases by 1.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (272,'Touchsight','Psychometabolism',NULL,NULL,'Psion/wilder 3','Visual','1 standard action','Personal; see text','You',NULL,NULL,'1 min./level (D)',NULL,'5',NULL,'Your telekinetic field tells you where everything is.',NULL,'\n      <p>You generate a subtle telekinetic field of mental contact, allowing you to \'feel\' your surroundings even in total darkness or when your sight would otherwise be obscured by your physical environment. Your <i>touchsight</i> field emanates from you out to 60 feet. You ignore invisibility, darkness, and concealment, though you must have line of effect to a creature or an object to discern it. You do not need to make Spot or Listen checks to notice creatures; you can detect and pinpoint all creatures within 60 feet. In many circumstances, comparing your regular senses to what you learn with <i>touchsight</i> is enough to tell you the difference between visible, invisible, hiding, and concealed creatures.</p>\n    ','<p><b>Augment:</b> For every 2 additional power points you spend, the radius of your <i>touchsight</i> field increases by 10 feet.</p><p/>\n','\n      <div topic=\"Touchsight\" level=\"5\"><p><h5>Touchsight</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>You generate a subtle telekinetic field of mental contact, allowing you to \'feel\' your surroundings even in total darkness or when your sight would otherwise be obscured by your physical environment. Your <i>touchsight</i> field emanates from you out to 60 feet. You ignore invisibility, darkness, and concealment, though you must have line of effect to a creature or an object to discern it. You do not need to make Spot or Listen checks to notice creatures; you can detect and pinpoint all creatures within 60 feet. In many circumstances, comparing your regular senses to what you learn with <i>touchsight</i> is enough to tell you the difference between visible, invisible, hiding, and concealed creatures.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every 2 additional power points you spend, the radius of your <i>touchsight</i> field increases by 10 feet.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (273,'Tower of Iron Will','Telepathy',NULL,'Mind-Affecting','Psion/wilder 5','Auditory','1 immediate action','10 ft.',NULL,'10-ft. -radius emanation centered on you',NULL,'1 round','None (harmless)','9','Yes (harmless)','Grant PR 19 against mind-affecting powers to all creatures within 10 ft. until your next turn.',NULL,'\n      <p>You generate a bastion of thought so strong that it offers protection to you and everyone around you, improving the self-control of all. You and all creatures in the power\'s area gain power resistance 19 against all mindaffecting powers.</p>\n      <p>You can manifest this power instantly, quickly enough to gain its benefits in an emergency. Manifesting the power is an immediate action.</p>\n      <p>You can use this power even when it is not your turn.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s duration increases by 1 round and the power resistance it provides increases by 1 point.</p><p/>\n','\n      <div topic=\"Tower of Iron Will\" level=\"5\"><p><h5>Tower of Iron Will</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 immediate action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius emanation centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>You generate a bastion of thought so strong that it offers protection to you and everyone around you, improving the self-control of all. You and all creatures in the power\'s area gain power resistance 19 against all mindaffecting powers.</p><p>You can manifest this power instantly, quickly enough to gain its benefits in an emergency. Manifesting the power is an immediate action.</p><p>You can use this power even when it is not your turn.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s duration increases by 1 round and the power resistance it provides increases by 1 point.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (274,'Trace Teleport','Clairsentience',NULL,NULL,'Psion/wilder 4','Visual','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'Spread with a radius of 25 ft. + 5 ft./2 levels, centered on you',NULL,'Instantaneous','None','7','No','Learn destination of subject\'s teleport.',NULL,'\n      <p>As <i>detect teleportation</i>, except you can trace the destination of any psionic or magical teleportation made by others within this power\'s area within the last minute.</p>\n      <p>You know the direction and distance the individuals traveled and could teleport to the location yourself if you so desired (and if you know the <i>psionic teleport</i> power), as if you had \'seen casually\' the location. This power does not grant you any information on the conditions at the other end of the trace beyond the mental coordinates of the location.</p>\n    ','<p><b>Augment:</b> If you spend 2 additional power points, this power\'s range increases to Medium (100 ft. + 10 ft./level).</p><p/>\n','\n      <div topic=\"Trace Teleport\" level=\"5\"><p><h5>Trace Teleport</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Spread with a radius of 25 ft. + 5 ft./2 levels, centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>As <i>detect teleportation</i>, except you can trace the destination of any psionic or magical teleportation made by others within this power\'s area within the last minute.</p><p>You know the direction and distance the individuals traveled and could teleport to the location yourself if you so desired (and if you know the <i>psionic teleport</i> power), as if you had \'seen casually\' the location. This power does not grant you any information on the conditions at the other end of the trace beyond the mental coordinates of the location.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> If you spend 2 additional power points, this power\'s range increases to Medium (100 ft. + 10 ft./level).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (275,'True Creation','Metacreativity','Creation',NULL,'Shaper 9',NULL,'10 minutes','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,NULL,'Instantaneous',NULL,'17, XP',NULL,'As psionic major creation, except items are completely real.','1/5 of the item\'s gold piece value, or a minimum of 1 XP.','\n      <p>As <i>psionic major creation</i>, except items created are enduring and cannot be negated by dispelling magic or negating powers. For all intents and purposes, these items are completely real.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"True Creation\" level=\"5\"><p><h5>True Creation</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Metacreativity (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Shaper 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>17, XP<br/></td></tr></table><p>As <i>psionic major creation</i>, except items created are enduring and cannot be negated by dispelling magic or negating powers. For all intents and purposes, these items are completely real.</p><p><i>XP Cost:</i> 1/5 of the item\'s gold piece value, or a minimum of 1 XP.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (276,'True Metabolism','Psychometabolism',NULL,NULL,'Psion/wilder 8','Material','1 round','Personal','You',NULL,NULL,'1 min./level',NULL,'15',NULL,'You regenerate 10 hit points/round.',NULL,'\n      <p>You are difficult to kill while this power persists. You automatically heal damage at the rate of 10 hit points per round.</p>\n      <p>This power is not effective against damage from starvation, thirst, or suffocation. Also, attack forms that don\'t deal hit point damage (for example, most poisons) ignore <i>true metabolism</i>. You can also use this power to regrow lost portions of your body and to reattach severed limbs or body parts, if you do nothing but concentrate on regrowing the lost body part or reattaching the severed limb for the duration of the power. You do not gain the benefits described earlier when you manifest <i>true metabolism</i> for this purpose. You must have a Constitution score to gain any of this power\'s benefits.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"True Metabolism\" level=\"5\"><p><h5>True Metabolism</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>15<br/></td></tr></table><p>You are difficult to kill while this power persists. You automatically heal damage at the rate of 10 hit points per round.</p><p>This power is not effective against damage from starvation, thirst, or suffocation. Also, attack forms that don\'t deal hit point damage (for example, most poisons) ignore <i>true metabolism</i>. You can also use this power to regrow lost portions of your body and to reattach severed limbs or body parts, if you do nothing but concentrate on regrowing the lost body part or reattaching the severed limb for the duration of the power. You do not gain the benefits described earlier when you manifest <i>true metabolism</i> for this purpose. You must have a Constitution score to gain any of this power\'s benefits.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (277,'True Seeing, Psionic','Clairsentience',NULL,NULL,'Psion/wilder 5','Visual','1 standard action','Personal','You',NULL,NULL,'1 min./level',NULL,'9',NULL,'See all things as they really are.',NULL,'\n      <p>As the <i>true seeing</i> power, except as noted here.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"True Seeing, Psionic\" level=\"5\"><p><h5>True Seeing, Psionic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>9<br/></td></tr></table><p>As the <i>true seeing</i> power, except as noted here.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (278,'Truevenom','Psychometabolism',NULL,NULL,'Psychic warrior 4','Material; see text','1 swift action','Personal','You',NULL,NULL,'1 min./level or until discharged','None and Fortitude negates; see text','7',NULL,'Your natural weapons are covered in horrible poison.',NULL,'\n      <p>If you have a claw attack (either from an actual natural weapon or from an effect such as <i>claws of the beast</i>), you can use this power to produce a horrible poison that coats one of your claws. On your next successful melee attack with the claw during the power\'s duration, the poison deals 1d8 points of Constitution damage immediately and another 1d8 points of Constitution damage 1 minute later. The target of your attack can negate each instance of damage with a Fortitude save.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Truevenom\" level=\"5\"><p><h5>Truevenom</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 swift action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level or until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None and Fortitude negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>If you have a claw attack (either from an actual natural weapon or from an effect such as <i>claws of the beast</i>), you can use this power to produce a horrible poison that coats one of your claws. On your next successful melee attack with the claw during the power\'s duration, the poison deals 1d8 points of Constitution damage immediately and another 1d8 points of Constitution damage 1 minute later. The target of your attack can negate each instance of damage with a Fortitude save.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (279,'Truevenom Weapon','Psychometabolism','Creation',NULL,'Psychic warrior 4','Material; see text','1 swift action','Touch','Weapon touched',NULL,NULL,'1 min./level or until discharged','None and Fortitude negates; see text','7',NULL,'Your weapon is horribly poisonous.',NULL,'\n      <p>As <i>truevenom</i>, except your weapon gains the poison coating as long as it remains in your grip, until the effect is discharged, or until the duration expires, whichever occurs first.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Truevenom Weapon\" level=\"5\"><p><h5>Truevenom Weapon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Weapon touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>As <i>truevenom</i>, except your weapon gains the poison coating as long as it remains in your grip, until the effect is discharged, or until the duration expires, whichever occurs first.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (280,'Ubiquitous Vision','Clairsentience',NULL,NULL,'Psion/wilder 3, psychic warrior 3','Visual','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)',NULL,'5',NULL,'You have all-around vision.',NULL,'\n      <p>You have metaphoric \'eyes in the back of your head,\' and on the sides and top as well, granting you benefits in specific situations. In effect, you have a 360-degree sphere of sight, allowing you a perfect view of creatures that might otherwise flank you. Thus, flanking opponents gain no bonus on their attack rolls, and rogues are denied their sneak attack ability because you do not lose your Dexterity bonus (but they may still sneak attack you if you are caught flat-footed). Your Spot and Search checks gain a +4 enhancement bonus. Concurrently, you take a -4 penalty on saves against all gaze attacks during the power\'s duration.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Ubiquitous Vision\" level=\"5\"><p><h5>Ubiquitous Vision</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Clairsentience<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 3, psychic warrior 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>You have metaphoric \'eyes in the back of your head,\' and on the sides and top as well, granting you benefits in specific situations. In effect, you have a 360-degree sphere of sight, allowing you a perfect view of creatures that might otherwise flank you. Thus, flanking opponents gain no bonus on their attack rolls, and rogues are denied their sneak attack ability because you do not lose your Dexterity bonus (but they may still sneak attack you if you are caught flat-footed). Your Spot and Search checks gain a +4 enhancement bonus. Concurrently, you take a -4 penalty on saves against all gaze attacks during the power\'s duration.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (281,'Ultrablast','Telepathy',NULL,'Mind-Affecting','Psion/wilder 7','Auditory; see text','1 standard action','15 ft.',NULL,'15-ft. -radius spread centered on you',NULL,'Instantaneous','Will half','13','Yes','Deal 13d6 damage in 15-ft. radius.',NULL,'\n      <p>You \'grumble\' psychically (which both psionic and nonpsionic creatures can detect), then release a horrid shriek from your subconscious that disrupts the brains of all enemies in the power\'s area, dealing 13d6 points of damage to each enemy.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d6 points.</p><p/>\n','\n      <div topic=\"Ultrablast\" level=\"5\"><p><h5>Ultrablast</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Telepathy [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Auditory; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>15 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>15-ft. -radius spread centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>13<br/></td></tr></table><p>You \'grumble\' psychically (which both psionic and nonpsionic creatures can detect), then release a horrid shriek from your subconscious that disrupts the brains of all enemies in the power\'s area, dealing 13d6 points of damage to each enemy.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, this power\'s damage increases by 1d6 points.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (282,'Vampiric Blade','Psychometabolism',NULL,NULL,'Psychic warrior 3','Material and visual','1 standard action','0 ft.','One weapon you hold',NULL,NULL,'1 round/level',NULL,'5',NULL,'You heal half of your base weapon damage.',NULL,'\n      <p>As <i>claws of the vampire</i>, except your weapon is affected as long as it remains in your grip or until this power\'s duration expires.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Vampiric Blade\" level=\"5\"><p><h5>Vampiric Blade</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material and visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One weapon you hold<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>5<br/></td></tr></table><p>As <i>claws of the vampire</i>, except your weapon is affected as long as it remains in your grip or until this power\'s duration expires.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (283,'Vigor','Psychometabolism',NULL,NULL,'Psion/wilder 1, psychic warrior 1','Material and olfactory','1 standard action','Personal','You',NULL,NULL,'1 min./level',NULL,'1',NULL,'Gain 5 temporary hit points.',NULL,'\n      <p>You suffuse yourself with power, gaining 5 temporary hit points. Using this power again when an earlier manifestation has not expired merely replaces the older temporary hit points (if any remain) with the newer ones.</p>\n    ','<p><b>Augment:</b> For every additional power point you spend, the number of temporary hit points you gain increases by 5.</p><p/>\n','\n      <div topic=\"Vigor\" level=\"5\"><p><h5>Vigor</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychometabolism<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 1, psychic warrior 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material and olfactory<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>1<br/></td></tr></table><p>You suffuse yourself with power, gaining 5 temporary hit points. Using this power again when an earlier manifestation has not expired merely replaces the older temporary hit points (if any remain) with the newer ones.</p><div topic=\"Augment\" level=\"8\"><p><b>Augment:</b> For every additional power point you spend, the number of temporary hit points you gain increases by 5.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (284,'Wall of Ectoplasm','Metacreativity','Creation',NULL,'Psion/wilder 4','Visual','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Wall whose area is up to one 10-ft. square/level or a sphere or hemisphere with a radius of up to 1 ft./level','1 min./level (D)','None','7','No','You create a protective barrier.',NULL,'\n      <p>You fashion a roiling wall of ectoplasm, imbuing it with solidity. The wall cannot move once it is formed. It is 1 inch thick per four manifester levels and occupies up to one 10-foot square per level. Each 10-foot square of the wall has 10 hit points per inch of thickness and hardness 5. A section of the wall whose hit points drop to 0 is breached. If a creature tries to break through the wall, the DC for the Strength check is 15 + 2 per inch of thickness.</p>\n      <p>The <i>wall of ectoplasm</i> is susceptible to <i>dispel psionics</i>, but it gains a +4 bonus on any check to determine whether the wall is negated. Spells, powers, and breath weapons cannot pass through the wall in either direction (though they could damage it). It blocks ethereal creatures as well as material creatures (though ethereal creatures can usually get around the wall by floating under or over it through material floors and ceilings). The wall is opaque, so neither vision nor gaze attacks operate through it. The wall does not block psychoportive travel, such as that provided by the <i>psionic teleport</i> power.</p>\n      <p>You can form the wall into a flat, vertical plane whose area is up to one 10-foot square per level or into a sphere or hemisphere with a radius of up to 1 foot per level.</p>\n      <p>The <i>wall of ectoplasm</i> must be continuous and unbroken when manifested. If its surface is interrupted by any object or creature, the power fails.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Wall of Ectoplasm\" level=\"5\"><p><h5>Wall of Ectoplasm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Metacreativity (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psion/wilder 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Wall whose area is up to one 10-ft. square/level or a sphere or hemisphere with a radius of up to 1 ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>You fashion a roiling wall of ectoplasm, imbuing it with solidity. The wall cannot move once it is formed. It is 1 inch thick per four manifester levels and occupies up to one 10-foot square per level. Each 10-foot square of the wall has 10 hit points per inch of thickness and hardness 5. A section of the wall whose hit points drop to 0 is breached. If a creature tries to break through the wall, the DC for the Strength check is 15 + 2 per inch of thickness.</p><p>The <i>wall of ectoplasm</i> is susceptible to <i>dispel psionics</i>, but it gains a +4 bonus on any check to determine whether the wall is negated. Spells, powers, and breath weapons cannot pass through the wall in either direction (though they could damage it). It blocks ethereal creatures as well as material creatures (though ethereal creatures can usually get around the wall by floating under or over it through material floors and ceilings). The wall is opaque, so neither vision nor gaze attacks operate through it. The wall does not block psychoportive travel, such as that provided by the <i>psionic teleport</i> power.</p><p>You can form the wall into a flat, vertical plane whose area is up to one 10-foot square per level or into a sphere or hemisphere with a radius of up to 1 foot per level.</p><p>The <i>wall of ectoplasm</i> must be continuous and unbroken when manifested. If its surface is interrupted by any object or creature, the power fails.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (285,'Wall Walker','Psychoportation',NULL,NULL,'Psychic warrior 2','Material','1 standard action','Personal','You',NULL,NULL,'1 min./level',NULL,'3',NULL,'Grants ability to walk on walls and ceilings.',NULL,'\n      <p>You can walk on vertical surfaces or even traverse ceilings (you need not make Climb checks to traverse these surfaces). Because of the need to keep at least one foot in contact with the wall or ceiling at all times, you cannot jump or use the run action, and you can move at only half speed.</p>\n      <p>You retain your Dexterity bonus to Armor Class, if any, and opponents gain no special bonuses against you.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Wall Walker\" level=\"5\"><p><h5>Wall Walker</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychoportation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Material<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Manifesting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>3<br/></td></tr></table><p>You can walk on vertical surfaces or even traverse ceilings (you need not make Climb checks to traverse these surfaces). Because of the need to keep at least one foot in contact with the wall or ceiling at all times, you cannot jump or use the run action, and you can move at only half speed.</p><p>You retain your Dexterity bonus to Armor Class, if any, and opponents gain no special bonuses against you.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO power VALUES (286,'Weapon of Energy','Psychokinesis',NULL,'see text','Psychic warrior 4','Visual','1 standard action','Touch','Weapon touched',NULL,NULL,'1 round/level','Fortitude negates (object, harmless)','7','None','Weapon deals additional energy damage.',NULL,'\n      <p>As <i>claw of energy</i>,  except this power can be manifested on a touched weapon. This power\'s subtype is the same as the type of energy infused in the touched weapon.</p>\n      <p/>\n    ',NULL,'\n      <div topic=\"Weapon of Energy\" level=\"5\"><p><h5>Weapon of Energy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Psychokinesis [see text]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Psychic warrior 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Display:</b><br/></td><td>Visual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Weapon touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (object, harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Resistance:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Power Points:</b><br/></td><td>7<br/></td></tr></table><p>As <i>claw of energy</i>,  except this power can be manifested on a touched weapon. This power\'s subtype is the same as the type of energy infused in the touched weapon.</p><p/>\n</div>\n    ','SRD 3.5 PsionicPowersQ-W');
INSERT INTO skill VALUES (1,'Appraise',NULL,'Int','No','No','No',NULL,'<p> You can appraise common or well-known objects with a DC 12 Appraise check. Failure means that you estimate the value at 50% to 150% (2d6+3 times 10%,) of its actual value.</p><p>Appraising a rare or exotic item requires a successful check against DC 15, 20, or higher. If the check is successful, you estimate the value correctly; failure means you cannot estimate the item\'s value.</p><p>A magnifying glass gives you a +2 circumstance bonus on Appraise checks involving any item that is small or highly detailed, such as a gem. A merchant\'s scale gives you a +2 circumstance bonus on Appraise checks involving any items that are valued by weight, including anything made of precious metals.</p><p>These bonuses stack.</p>\n','Appraising an item takes 1 minute (ten consecutive full-round actions).','No. You cannot try again on the same object, regardless of success.','A dwarf gets a +2 racial bonus on Appraise checks that are related to stone or metal items because dwarves are familiar with valuable items of all kinds (especially those made of stone or metal).The master of a raven familiar gains a +3 bonus on Appraise checks.A character with the Diligent feat gets a +2 bonus on Appraise checks.',NULL,'If you have 5 ranks in any Craft skill, you gain a +2 bonus on Appraise checks related to items made with that Craft skill.','\n      <p>The character can sense magical auras in objects.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Detect magic<br/></td>\n<td>50<br/></td>\n\n</tr>\n</table>\n      <div topic=\"Detect Magic\" level=\"8\"><p><b>Detect Magic:</b> The character can sense if an item has a magical aura. He or she can then use Spellcraft to learn more about the item as if he or she had already cast <i>detect magic</i> on the item. This requires a full-round action.</p><p/><p/>\n</div>\n    ','For common items, failure on an untrained check means no estimate. For rare items, success means an estimate of 50% to 150% (2d6+3 times 10%).','\n      <div topic=\"Appraise\" level=\"3\"><p><h3>Appraise (Int)</h3></p><div topic=\"Check\" level=\"8\"><p> You can appraise common or well-known objects with a DC 12 Appraise check. Failure means that you estimate the value at 50% to 150% (2d6+3 times 10%,) of its actual value.</p><p>Appraising a rare or exotic item requires a successful check against DC 15, 20, or higher. If the check is successful, you estimate the value correctly; failure means you cannot estimate the item\'s value.</p><p>A magnifying glass gives you a +2 circumstance bonus on Appraise checks involving any item that is small or highly detailed, such as a gem. A merchant\'s scale gives you a +2 circumstance bonus on Appraise checks involving any items that are valued by weight, including anything made of precious metals.</p><p>These bonuses stack.</p>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> Appraising an item takes 1 minute (ten consecutive full-round actions).</p>\n</div><div topic=\"Try Again\" level=\"8\"><p><b>Try Again:</b> No. You cannot try again on the same object, regardless of success.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A dwarf gets a +2 racial bonus on Appraise checks that are related to stone or metal items because dwarves are familiar with valuable items of all kinds (especially those made of stone or metal).</p><p>The master of a raven familiar gains a +3 bonus on Appraise checks.</p><p>A character with the Diligent feat gets a +2 bonus on Appraise checks.</p>\n</div><div topic=\"Synergy\" level=\"8\"><p><b>Synergy:</b> If you have 5 ranks in any Craft skill, you gain a +2 bonus on Appraise checks related to items made with that Craft skill.</p>\n</div><div topic=\"Untrained\" level=\"8\"><p><b>Untrained:</b> For common items, failure on an untrained check means no estimate. For rare items, success means an estimate of 50% to 150% (2d6+3 times 10%).</p>\n</div><div topic=\"Epic Use\" level=\"5\"><p><h5>Epic Use</h5></p><p>The character can sense magical auras in objects.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Detect magic<br/></td>\n<td>50<br/></td>\n\n</tr>\n</table><div topic=\"Detect Magic\" level=\"8\"><p><b>Detect Magic:</b> The character can sense if an item has a magical aura. He or she can then use Spellcraft to learn more about the item as if he or she had already cast <i>detect magic</i> on the item. This requires a full-round action.</p><p/><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (2,'Autohypnosis',NULL,'Wis','Yes','Yes','No','<p> You have trained your mind to gain mastery over your body and the mind\'s own deepest capabilities.</p>\n','<p> The DC and the effect of a successful check depend on the task you attempt.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Ignore caltrop wound<br/></td>\n<td>18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Memorize<br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Resist dying<br/></td>\n<td>20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Resist fear<br/></td>\n<td>Fear effect DC<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tolerate poison<br/></td>\n<td>Poison\'s DC<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Willpower<br/></td>\n<td>20<br/></td>\n\n</tr>\n</table><p><i>Ignore Caltrop Wound:</i> If you are wounded by stepping on a caltrop, your speed is reduced to one-half normal. A successful Autohypnosis check removes this movement penalty. The wound doesn\'t go away-it is just ignored through self-persuasion.</p><p><i>Memorize:</i> You can attempt to memorize a long string of numbers, a long passage of verse, or some other particularly difficult piece of information (but you can\'t memorize magical writing or similarly exotic scripts). Each successful check allows you to memorize a single page of text (up to 800 words), numbers, diagrams, or sigils (even if you don\'t recognize their meaning). If a document is longer than one page, you can make additional checks for each additional page. You always retain this information; however, you can recall it only with another successful Autohypnosis check.</p><p><i>Resist Dying:</i> You can attempt to subconsciously prevent yourself from dying. If you have negative hit points and are losing hit points (at 1 per round, 1 per hour), you can substitute a DC 20 Autohypnosis check for your d% roll to see if you become stable. If the check is successful, you stop losing hit points (you do not gain any hit points, however, as a result of the check). You can substitute this check for the d% roll in later rounds if you are initially unsuccessful.</p><p><i>Resist Fear:</i> In response to any fear effect, you make a saving throw normally. If you fail the saving throw, you can make an Autohypnosis check on your next round even while overcome by fear. If your autohypnosis check meets or beats the DC for the fear effect, you shrug off the fear. On a failed check, the fear affects you normally, and you gain no further attempts to shrug off that particular fear effect.</p><p><i>Tolerate Poison:</i> You can choose to substitute an Autohypnosis check for a saving throw against any standard poison\'s secondary damage or effect. This skill has no effect on the initial saving throw against poison.</p><p><i>Willpower:</i> If reduced to 0 hit points (disabled), you can make an Autohypnosis check. If successful, you can take a normal action while at 0 hit points without taking 1 point of damage. You must make a check for each strenuous action you want to take. A failed Autohypnosis check in this circumstance carries no direct penalty-you can choose not to take the strenuous action and thus avoid the hit point loss. If you do so anyway, you drop to -1 hit points, as normal when disabled.</p>\n','None. Making an Autohypnosis check doesn\'t require an action; it is either a free action (when attempted reactively) or part of another action (when attempted actively).','Yes, for memorize and willpower uses, though a success doesn\'t cancel the effects of a previous failure. No for the other uses.',NULL,NULL,'If you have 5 or more ranks in Autohypnosis, you get a +2 bonus on Knowledge (psionics) checks.If you have 5 or more ranks in Concentration, you get a +2 bonus on Autohypnosis checks.','\n      <p>The character has trained his or her mind to ignore poison, resist mental influence, and convince his or her body that he or she is tougher than normal.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>DC</b><br/></td>\n<td><b>Task</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Poison\'s DC + 5<br/></td>\n<td>When poisoned, the character can make an Autohypnosis check on his or her next action. A successful check indicates the character does not have to make a saving throw against the poison\'s secondary damage, which he or she instead automatically ignores.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>50<br/></td>\n<td>If a failed saving throw indicates the character is affected by any mind-affecting powers, spells, or spell-like effects, a successful Autohypnosis check allows an immediate second saving throw to resist the effect. If the mind-affecting effect normally does not allow a saving throw, a successful Autohypnosis check allows a saving throw.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>60<br/></td>\n<td>With a successful Autohypnosis check, the character gains temporary hit points equal to 10 + his or her Wisdom modifier. The temporary hit points persist until lost. A character cannot check for temporary hit points more than once per day. Temporary hit points gained through Autohypnosis do not stack with temporary hit points gained through any other source<br/></td>\n\n</tr>\n</table>\n      <p/>\n      <p>Mortal wounds are less lethal for the character.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>DC</b><br/></td> <td><b>Task</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>30<br/></td>\n<td>If reduced to negative hit points but not dead, make an Autohypnosis check. If successful, the character does not go unconscious and can continue taking actions until he or she bleeds to death or stabilizes (the character can also continue making stabilization checks). If healed or stabilized, the character continues to take actions normally.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>60<br/></td>\n<td>On a successful Autohypnosis check, the character gains damage reduction 2/-. The damage reduction lasts for 12 hours. The character cannot check for damage reduction more than once per day. Damage reduction gained through Autohypnosis does not stack with damage reduction gained through any other source.<br/></td>\n\n</tr>\n</table>\n      <p/>\n      <p/>\n      <p/>\n      <p/>\n    ',NULL,'\n      <div topic=\"Autohypnosis\" level=\"3\"><p><h3>Autohypnosis (Wis; Trained Only; Psionic)</h3></p><div topic=\"Description\" level=\"8\"><p> You have trained your mind to gain mastery over your body and the mind\'s own deepest capabilities.</p>\n</div><div topic=\"Check\" level=\"8\"><p> The DC and the effect of a successful check depend on the task you attempt.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Ignore caltrop wound<br/></td>\n<td>18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Memorize<br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Resist dying<br/></td>\n<td>20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Resist fear<br/></td>\n<td>Fear effect DC<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tolerate poison<br/></td>\n<td>Poison\'s DC<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Willpower<br/></td>\n<td>20<br/></td>\n\n</tr>\n</table><p><i>Ignore Caltrop Wound:</i> If you are wounded by stepping on a caltrop, your speed is reduced to one-half normal. A successful Autohypnosis check removes this movement penalty. The wound doesn\'t go away-it is just ignored through self-persuasion.</p><p><i>Memorize:</i> You can attempt to memorize a long string of numbers, a long passage of verse, or some other particularly difficult piece of information (but you can\'t memorize magical writing or similarly exotic scripts). Each successful check allows you to memorize a single page of text (up to 800 words), numbers, diagrams, or sigils (even if you don\'t recognize their meaning). If a document is longer than one page, you can make additional checks for each additional page. You always retain this information; however, you can recall it only with another successful Autohypnosis check.</p><p><i>Resist Dying:</i> You can attempt to subconsciously prevent yourself from dying. If you have negative hit points and are losing hit points (at 1 per round, 1 per hour), you can substitute a DC 20 Autohypnosis check for your d% roll to see if you become stable. If the check is successful, you stop losing hit points (you do not gain any hit points, however, as a result of the check). You can substitute this check for the d% roll in later rounds if you are initially unsuccessful.</p><p><i>Resist Fear:</i> In response to any fear effect, you make a saving throw normally. If you fail the saving throw, you can make an Autohypnosis check on your next round even while overcome by fear. If your autohypnosis check meets or beats the DC for the fear effect, you shrug off the fear. On a failed check, the fear affects you normally, and you gain no further attempts to shrug off that particular fear effect.</p><p><i>Tolerate Poison:</i> You can choose to substitute an Autohypnosis check for a saving throw against any standard poison\'s secondary damage or effect. This skill has no effect on the initial saving throw against poison.</p><p><i>Willpower:</i> If reduced to 0 hit points (disabled), you can make an Autohypnosis check. If successful, you can take a normal action while at 0 hit points without taking 1 point of damage. You must make a check for each strenuous action you want to take. A failed Autohypnosis check in this circumstance carries no direct penalty-you can choose not to take the strenuous action and thus avoid the hit point loss. If you do so anyway, you drop to -1 hit points, as normal when disabled.</p>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> None. Making an Autohypnosis check doesn\'t require an action; it is either a free action (when attempted reactively) or part of another action (when attempted actively).</p>\n</div><div topic=\"Try Again\" level=\"8\"><p><b>Try Again:</b> Yes, for memorize and willpower uses, though a success doesn\'t cancel the effects of a previous failure. No for the other uses.</p>\n</div><div topic=\"Synergy\" level=\"8\"><p><b>Synergy:</b> If you have 5 or more ranks in Autohypnosis, you get a +2 bonus on Knowledge (psionics) checks.</p><p>If you have 5 or more ranks in Concentration, you get a +2 bonus on Autohypnosis checks.</p>\n</div><div topic=\"Epic Use\" level=\"5\"><p><h5>Epic Use</h5></p><p>The character has trained his or her mind to ignore poison, resist mental influence, and convince his or her body that he or she is tougher than normal.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>DC</b><br/></td>\n<td><b>Task</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Poison\'s DC + 5<br/></td>\n<td>When poisoned, the character can make an Autohypnosis check on his or her next action. A successful check indicates the character does not have to make a saving throw against the poison\'s secondary damage, which he or she instead automatically ignores.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>50<br/></td>\n<td>If a failed saving throw indicates the character is affected by any mind-affecting powers, spells, or spell-like effects, a successful Autohypnosis check allows an immediate second saving throw to resist the effect. If the mind-affecting effect normally does not allow a saving throw, a successful Autohypnosis check allows a saving throw.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>60<br/></td>\n<td>With a successful Autohypnosis check, the character gains temporary hit points equal to 10 + his or her Wisdom modifier. The temporary hit points persist until lost. A character cannot check for temporary hit points more than once per day. Temporary hit points gained through Autohypnosis do not stack with temporary hit points gained through any other source<br/></td>\n\n</tr>\n</table><p/><p>Mortal wounds are less lethal for the character.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>DC</b><br/></td> <td><b>Task</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>30<br/></td>\n<td>If reduced to negative hit points but not dead, make an Autohypnosis check. If successful, the character does not go unconscious and can continue taking actions until he or she bleeds to death or stabilizes (the character can also continue making stabilization checks). If healed or stabilized, the character continues to take actions normally.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>60<br/></td>\n<td>On a successful Autohypnosis check, the character gains damage reduction 2/-. The damage reduction lasts for 12 hours. The character cannot check for damage reduction more than once per day. Damage reduction gained through Autohypnosis does not stack with damage reduction gained through any other source.<br/></td>\n\n</tr>\n</table><p/><p/><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (3,'Balance',NULL,'Dex','No','No','Yes',NULL,'<p> You can walk on a precarious surface. A successful check lets you move at half your speed along the surface for 1 round. A failure by 4 or less means you can\'t move for 1 round. A failure by 5 or more means you fall. The difficulty varies with the surface, as follows:</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Narrow Surface</b> <br/></td>\n<td><b>Balance DC</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Difficult Surface</b><br/></td>\n<td><b>Balance DC</b>\n<sup><b>1</b></sup><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>7-12 inches wide<br/></td>\n<td>10<br/></td>\n<td>Uneven flagstone<br/></td>\n<td>102<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>2-6 inches wide<br/></td>\n<td>15<br/></td>\n<td>Hewn stone floor<br/></td>\n<td>102<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Less than 2 inches wide<br/></td>\n<td>20<br/></td>\n<td>Sloped or angled floor<br/></td>\n<td>102<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\">1 Add modifiers from Narrow Surface Modifiers, below, as appropriate.<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\">2 Only if running or charging. Failure by 4 or less means the character can\'t run or charge, but may otherwise act normally.<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Narrow Surface Modifiers</b><br/></td>\n<td/>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Surface</b> <br/></td>\n<td><b>DC Modifier</b>\n<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Lightly obstructed<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Severely obstructed<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Lightly slippery<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Severely slippery<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Sloped or angled<br/></td>\n<td>+2<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 Add the appropriate modifier to the Balance DC of a narrow surface.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">These modifiers stack.<br/></td>\n\n</tr>\n</table><p/><p><i>Being Attacked while Balancing:</i> You are considered flat-footed while balancing, since you can\'t move to avoid a blow, and thus you lose your Dexterity bonus to AC (if any). If you have 5 or more ranks in Balance, you aren\'t considered flat-footed while balancing. If you take damage while balancing, you must make another Balance check against the same DC to remain standing.</p><p><i>Accelerated Movement:</i> You can try to walk across a precarious surface more quickly than normal. If you accept a -5 penalty, you can move your full speed as a move action. (Moving twice your speed in a round requires two Balance checks, one for each move action used.) You may also accept this penalty in order to charge across a precarious surface; charging requires one Balance check for each multiple of your speed (or fraction thereof ) that you charge.</p>\n','None. A Balance check doesn\'t require an action; it is made as part of another action or as a reaction to a situation.',NULL,'If you have the Agile feat, you get a +2 bonus on Balance checks.',NULL,'If you have 5 or more ranks in Tumble, you get a +2 bonus on Balance checks.','\n      <p/>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Surface</b><br/></td>\n<td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1-2 inches wide<br/></td>\n<td>20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to 1 inch wide<br/></td>\n<td>40<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Hair-thin<br/></td>\n<td>60<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Liquid*<br/></td>\n<td>90<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Cloud<br/></td>\n<td>120<br/></td>\n\n</tr>\n</table>\n      <p>*Includes any other surface that couldn\'t support the character\'s weight, such as a fragile branch.</p>\n      <p/>\n      <p/>\n    ',NULL,'\n      <div topic=\"Balance\" level=\"3\"><p><h3>Balance (Dex; Armor Check Penalty)</h3></p><div topic=\"Check\" level=\"8\"><p> You can walk on a precarious surface. A successful check lets you move at half your speed along the surface for 1 round. A failure by 4 or less means you can\'t move for 1 round. A failure by 5 or more means you fall. The difficulty varies with the surface, as follows:</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Narrow Surface</b> <br/></td>\n<td><b>Balance DC</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Difficult Surface</b><br/></td>\n<td><b>Balance DC</b>\n<sup><b>1</b></sup><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>7-12 inches wide<br/></td>\n<td>10<br/></td>\n<td>Uneven flagstone<br/></td>\n<td>102<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>2-6 inches wide<br/></td>\n<td>15<br/></td>\n<td>Hewn stone floor<br/></td>\n<td>102<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Less than 2 inches wide<br/></td>\n<td>20<br/></td>\n<td>Sloped or angled floor<br/></td>\n<td>102<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\">1 Add modifiers from Narrow Surface Modifiers, below, as appropriate.<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\">2 Only if running or charging. Failure by 4 or less means the character can\'t run or charge, but may otherwise act normally.<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Narrow Surface Modifiers</b><br/></td>\n<td/>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Surface</b> <br/></td>\n<td><b>DC Modifier</b>\n<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Lightly obstructed<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Severely obstructed<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Lightly slippery<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Severely slippery<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Sloped or angled<br/></td>\n<td>+2<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 Add the appropriate modifier to the Balance DC of a narrow surface.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">These modifiers stack.<br/></td>\n\n</tr>\n</table><p/><p><i>Being Attacked while Balancing:</i> You are considered flat-footed while balancing, since you can\'t move to avoid a blow, and thus you lose your Dexterity bonus to AC (if any). If you have 5 or more ranks in Balance, you aren\'t considered flat-footed while balancing. If you take damage while balancing, you must make another Balance check against the same DC to remain standing.</p><p><i>Accelerated Movement:</i> You can try to walk across a precarious surface more quickly than normal. If you accept a -5 penalty, you can move your full speed as a move action. (Moving twice your speed in a round requires two Balance checks, one for each move action used.) You may also accept this penalty in order to charge across a precarious surface; charging requires one Balance check for each multiple of your speed (or fraction thereof ) that you charge.</p>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> None. A Balance check doesn\'t require an action; it is made as part of another action or as a reaction to a situation.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> If you have the Agile feat, you get a +2 bonus on Balance checks.</p>\n</div><div topic=\"Synergy\" level=\"8\"><p><b>Synergy:</b> If you have 5 or more ranks in Tumble, you get a +2 bonus on Balance checks.</p>\n</div><div topic=\"Epic Use\" level=\"5\"><p><h5>Epic Use</h5></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Surface</b><br/></td>\n<td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1-2 inches wide<br/></td>\n<td>20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to 1 inch wide<br/></td>\n<td>40<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Hair-thin<br/></td>\n<td>60<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Liquid*<br/></td>\n<td>90<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Cloud<br/></td>\n<td>120<br/></td>\n\n</tr>\n</table><p>*Includes any other surface that couldn\'t support the character\'s weight, such as a fragile branch.</p><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (4,'Bluff',NULL,'Cha','No','No','No',NULL,'<p> A Bluff check is opposed by the target\'s Sense Motive check. See the accompanying table for examples of different kinds of bluffs and the modifier to the target\'s Sense Motive check for each one.</p><p>Favorable and unfavorable circumstances weigh heavily on the outcome of a bluff. Two circumstances can weigh against you: The bluff is hard to believe, or the action that the target is asked to take goes against its self-interest, nature, personality, orders, or the like. If it\'s important, you can distinguish between a bluff that fails because the target doesn\'t believe it and one that fails because it just asks too much of the target. For instance, if the target gets a +10 bonus on its Sense Motive check because the bluff demands something risky, and the Sense Motive check succeeds by 10 or less, then the target didn\'t so much see through the bluff as prove reluctant to go along with it. A target that succeeds by 11 or more has seen through the bluff.</p><p>A successful Bluff check indicates that the target reacts as you wish, at least for a short time (usually 1 round or less) or believes something that you want it to believe. Bluff, however, is not a <i>suggestion</i> spell.</p><p>A bluff requires interaction between you and the target. Creatures unaware of you cannot be bluffed.</p><p><i>Feinting in Combat:</i> You can also use Bluff to mislead an opponent in melee combat (so that it can\'t dodge your next attack effectively). To feint, make a Bluff check opposed by your target\'s Sense Motive check, but in this case, the target may add its base attack bonus to the roll along with any other applicable modifiers.</p><p>If your Bluff check result exceeds this special Sense Motive check result, your target is denied its Dexterity bonus to AC (if any) for the next melee attack you make against it. This attack must be made on or before your next turn.</p><p>Feinting in this way against a nonhumanoid is difficult because it\'s harder to read a strange creature\'s body language; you take a -4 penalty on your Bluff check. Against a creature of animal Intelligence (1 or 2) it\'s even harder; you take a -8 penalty. Against a nonintelligent creature, it\'s impossible.</p><p>Feinting in combat does not provoke an attack of opportunity.</p><p><i>Creating a Diversion to Hide:</i> You can use the Bluff skill to help you hide. A successful Bluff check gives you the momentary diversion you need to attempt a Hide check while people are aware of you. This usage does not provoke an attack of opportunity.</p><p><i>Delivering a Secret Message:</i> You can use Bluff to get a message across to another character without others understanding it. The DC is 15 for simple messages, or 20 for complex messages, especially those that rely on getting across new information. Failure by 4 or less means you can\'t get the message across. Failure by 5 or more means that some false information has been implied or inferred. Anyone listening to the exchange can make a Sense Motive check opposed by the Bluff check you made to transmit in order to intercept your message (see Sense Motive).</p>\n','Varies. A Bluff check made as part of general interaction always takes at least 1 round (and is at least a full-round action), but it can take much longer if you try something elaborate. A Bluff check made to feint in combat or create a diversion to hide is a standard action. A Bluff check made to deliver a secret message doesn\'t take an action; it is part of normal communication.','Varies. Generally, a failed Bluff check in social interaction makes the target too suspicious for you to try again in the same circumstances, but you may retry freely on Bluff checks made to feint in combat. Retries are also allowed when you are trying to send a message, but you may attempt such a retry only once per round.Each retry carries the same chance of miscommunication.','A ranger gains a bonus on Bluff checks when using this skill against a favored enemy.The master of a snake familiar gains a +3 bonus on Bluff checks.If you have the Persuasive feat, you get a +2 bonus on Bluff checks.',NULL,'If you have 5 or more ranks in Bluff, you get a +2 bonus on Diplomacy, Intimidate, and Sleight of Hand checks, as well as on Disguise checks made when you know you\'re being observed and you try to act in character.\n\n\nBluff Examples \n\n\n\nExample Circumstances\nSense Motive Modifier\n\n\n\nThe target wants to believe you.\n-5\n\n\n\nThe bluff is believable and doesn\'t affect the target much.\n+0\n\n\n\nThe bluff is a little hard to believe or puts the target at some risk.\n+5\n\n\n\nThe bluff is hard to believe or puts the target at significant risk.\n+10\n\n\n\n\nThe bluff is way out there, almost too incredible to consider.\n+20','\n      <p>The character can implant a nonmagical suggestion in a target, display a false alignment, or disguise his or her surface thoughts.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Example Circumstance</b><br/></td>\n<td><b>Sense Motive Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Instill suggestion in target<br/></td>\n<td>+50<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC</b> <br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Display false alignment<br/></td>\n<td>70<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Disguise surface thoughts<br/></td>\n<td>100<br/></td>\n\n</tr>\n</table>\n      <div topic=\"Instill Suggestion in Target\" level=\"8\"><p><b>Instill Suggestion in Target:</b> This is identical to the effect of the <i>suggestion</i> spell, except that it is nonmagical and lasts for only 10 minutes. It can be sensed as if it were an enchantment effect (Sense Motive DC 25).</p>\n</div>\n      <div topic=\"Display False Alignment\" level=\"8\"><p><b>Display False Alignment:</b> The character can fool alignment-sensing effects by displaying a false alignment of his or her choice. Once set, a false alignment remains as long as the character remains conscious and awake. Setting or changing a false alignment requires a full-round action.</p>\n</div>\n      <div topic=\"Disguise Surface Thoughts\" level=\"8\"><p><b>Disguise Surface Thoughts:</b> The character can fool spells such as <i>detect thoughts</i> (or similar effects) by displaying false surface thoughts. While the character can\'t completely mask the presence of his or her thoughts, he or she can change his or her apparent Intelligence score (and thus the character\'s apparent mental strength) by as much as 10 points and can place any thought in his or her \'surface thoughts\' to be read by such spells or effects. If a character attempts to use Sense Motive to detect his or her surface thoughts (see the Sense Motive skill description), this becomes an opposed check (though any result lower than 100 automatically fails).</p><p/><p/>\n</div>\n    ',NULL,'\n      <div topic=\"Bluff\" level=\"3\"><p><h3>Bluff (Cha)</h3></p><div topic=\"Check\" level=\"8\"><p> A Bluff check is opposed by the target\'s Sense Motive check. See the accompanying table for examples of different kinds of bluffs and the modifier to the target\'s Sense Motive check for each one.</p><p>Favorable and unfavorable circumstances weigh heavily on the outcome of a bluff. Two circumstances can weigh against you: The bluff is hard to believe, or the action that the target is asked to take goes against its self-interest, nature, personality, orders, or the like. If it\'s important, you can distinguish between a bluff that fails because the target doesn\'t believe it and one that fails because it just asks too much of the target. For instance, if the target gets a +10 bonus on its Sense Motive check because the bluff demands something risky, and the Sense Motive check succeeds by 10 or less, then the target didn\'t so much see through the bluff as prove reluctant to go along with it. A target that succeeds by 11 or more has seen through the bluff.</p><p>A successful Bluff check indicates that the target reacts as you wish, at least for a short time (usually 1 round or less) or believes something that you want it to believe. Bluff, however, is not a <i>suggestion</i> spell.</p><p>A bluff requires interaction between you and the target. Creatures unaware of you cannot be bluffed.</p><p><i>Feinting in Combat:</i> You can also use Bluff to mislead an opponent in melee combat (so that it can\'t dodge your next attack effectively). To feint, make a Bluff check opposed by your target\'s Sense Motive check, but in this case, the target may add its base attack bonus to the roll along with any other applicable modifiers.</p><p>If your Bluff check result exceeds this special Sense Motive check result, your target is denied its Dexterity bonus to AC (if any) for the next melee attack you make against it. This attack must be made on or before your next turn.</p><p>Feinting in this way against a nonhumanoid is difficult because it\'s harder to read a strange creature\'s body language; you take a -4 penalty on your Bluff check. Against a creature of animal Intelligence (1 or 2) it\'s even harder; you take a -8 penalty. Against a nonintelligent creature, it\'s impossible.</p><p>Feinting in combat does not provoke an attack of opportunity.</p><p><i>Creating a Diversion to Hide:</i> You can use the Bluff skill to help you hide. A successful Bluff check gives you the momentary diversion you need to attempt a Hide check while people are aware of you. This usage does not provoke an attack of opportunity.</p><p><i>Delivering a Secret Message:</i> You can use Bluff to get a message across to another character without others understanding it. The DC is 15 for simple messages, or 20 for complex messages, especially those that rely on getting across new information. Failure by 4 or less means you can\'t get the message across. Failure by 5 or more means that some false information has been implied or inferred. Anyone listening to the exchange can make a Sense Motive check opposed by the Bluff check you made to transmit in order to intercept your message (see Sense Motive).</p>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> Varies. A Bluff check made as part of general interaction always takes at least 1 round (and is at least a full-round action), but it can take much longer if you try something elaborate. A Bluff check made to feint in combat or create a diversion to hide is a standard action. A Bluff check made to deliver a secret message doesn\'t take an action; it is part of normal communication.</p>\n</div><div topic=\"Try Again\" level=\"8\"><p><b>Try Again:</b> Varies. Generally, a failed Bluff check in social interaction makes the target too suspicious for you to try again in the same circumstances, but you may retry freely on Bluff checks made to feint in combat. Retries are also allowed when you are trying to send a message, but you may attempt such a retry only once per round.</p><p>Each retry carries the same chance of miscommunication.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A ranger gains a bonus on Bluff checks when using this skill against a favored enemy.</p><p>The master of a snake familiar gains a +3 bonus on Bluff checks.</p><p>If you have the Persuasive feat, you get a +2 bonus on Bluff checks.</p>\n</div><div topic=\"Synergy\" level=\"8\"><p><b>Synergy:</b> If you have 5 or more ranks in Bluff, you get a +2 bonus on Diplomacy, Intimidate, and Sleight of Hand checks, as well as on Disguise checks made when you know you\'re being observed and you try to act in character.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\"><b>Bluff Examples</b><br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Example Circumstances</b><br/></td>\n<td><b>Sense Motive Modifier</b><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>The target wants to believe you.<br/></td>\n<td>-5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>The bluff is believable and doesn\'t affect the target much.<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>The bluff is a little hard to believe or puts the target at some risk.<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>The bluff is hard to believe or puts the target at significant risk.<br/></td>\n<td>+10<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>The bluff is way out there, almost too incredible to consider.<br/></td>\n<td>+20<br/></td>\n\n</tr>\n</table><p/>\n</div><div topic=\"Epic Use\" level=\"5\"><p><h5>Epic Use</h5></p><p>The character can implant a nonmagical suggestion in a target, display a false alignment, or disguise his or her surface thoughts.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Example Circumstance</b><br/></td>\n<td><b>Sense Motive Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Instill suggestion in target<br/></td>\n<td>+50<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC</b> <br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Display false alignment<br/></td>\n<td>70<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Disguise surface thoughts<br/></td>\n<td>100<br/></td>\n\n</tr>\n</table><div topic=\"Instill Suggestion in Target\" level=\"8\"><p><b>Instill Suggestion in Target:</b> This is identical to the effect of the <i>suggestion</i> spell, except that it is nonmagical and lasts for only 10 minutes. It can be sensed as if it were an enchantment effect (Sense Motive DC 25).</p>\n</div><div topic=\"Display False Alignment\" level=\"8\"><p><b>Display False Alignment:</b> The character can fool alignment-sensing effects by displaying a false alignment of his or her choice. Once set, a false alignment remains as long as the character remains conscious and awake. Setting or changing a false alignment requires a full-round action.</p>\n</div><div topic=\"Disguise Surface Thoughts\" level=\"8\"><p><b>Disguise Surface Thoughts:</b> The character can fool spells such as <i>detect thoughts</i> (or similar effects) by displaying false surface thoughts. While the character can\'t completely mask the presence of his or her thoughts, he or she can change his or her apparent Intelligence score (and thus the character\'s apparent mental strength) by as much as 10 points and can place any thought in his or her \'surface thoughts\' to be read by such spells or effects. If a character attempts to use Sense Motive to detect his or her surface thoughts (see the Sense Motive skill description), this becomes an opposed check (though any result lower than 100 automatically fails).</p><p/><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (5,'Climb',NULL,'Str','No','No','Yes',NULL,'<p> With a successful Climb check, you can advance up, down, or across a slope, a wall, or some other steep incline (or even a ceiling with handholds) at one-quarter your normal speed. A slope is considered to be any incline at an angle measuring less than 60 degrees; a wall is any incline at an angle measuring 60 degrees or more.</p><p>A Climb check that fails by 4 or less means that you make no progress, and one that fails by 5 or more means that you fall from whatever height you have already attained.</p><p>A climber\'s kit gives you a +2 circumstance bonus on Climb checks.</p><p>The DC of the check depends on the conditions of the climb. Compare the task with those on the following table to determine an appropriate DC.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Climb DC</b> <br/></td>\n<td><b>Example Surface or Activity</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>0<br/></td>\n<td>A slope too steep to walk up, or a knotted rope with a wall to brace against.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5<br/></td>\n<td>A rope with a wall to brace against, or a knotted rope, or a rope affected by the <i>rope trick</i> spell.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>A surface with ledges to hold on to and stand on, such as a very rough wall or a ship\'s rigging.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Any surface with adequate handholds and footholds (natural or artificial), such as a very rough natural rock surface or a tree, or an unknotted rope, or pulling yourself up when dangling by your hands.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>An uneven surface with some narrow handholds and footholds, such as a typical wall in a dungeon or ruins.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>25<br/></td>\n<td>A rough surface, such as a natural rock wall or a brick wall.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>25<br/></td>\n<td>An overhang or ceiling with handholds but no footholds.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>-<br/></td>\n<td>A perfectly smooth, flat, vertical surface cannot be climbed.<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Climb DC Modifier</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Example Surface or Activity</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>-10<br/></td>\n<td>Climbing a chimney (artificial or natural) or other location where you can brace against two opposite walls (reduces DC by 10).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>-5<br/></td>\n<td>Climbing a corner where you can brace against perpendicular walls (reduces DC by 5).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>+5<br/></td>\n<td>Surface is slippery (increases DC by 5).<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1These modifiers are cumulative; use any that apply.<br/></td>\n\n</tr>\n</table><p/><p>You need both hands free to climb, but you may cling to a wall with one hand while you cast a spell or take some other action that requires only one hand. While climbing, you can\'t move to avoid a blow, so you lose your Dexterity bonus to AC (if any). You also can\'t use a shield while climbing.</p><p>Any time you take damage while climbing, make a Climb check against the DC of the slope or wall. Failure means you fall from your current height and sustain the appropriate falling damage.</p><p><i>Accelerated Climbing:</i> You try to climb more quickly than normal. By accepting a -5 penalty, you can move half your speed (instead of one-quarter your speed).</p><p><i>Making Your Own Handholds and Footholds:</i> You can make your own handholds and footholds by pounding pitons into a wall. Doing so takes 1 minute per piton, and one piton is needed per 3 feet of distance. As with any surface that offers handholds and footholds, a wall with pitons in it has a DC of 15. In the same way, a climber with a handaxe or similar implement can cut handholds in an ice wall.</p><p><i>Catching Yourself When Falling:</i> It\'s practically impossible to catch yourself on a wall while falling. Make a Climb check (DC = wall\'s DC + 20) to do so. It\'s much easier to catch yourself on a slope (DC = slope\'s DC + 10).</p><p><i>Catching a Falling Character While Climbing:</i> If someone climbing above you or adjacent to you falls, you can attempt to catch the falling character if he or she is within your reach. Doing so requires a successful melee touch attack against the falling character (though he or she can voluntarily forego any Dexterity bonus to AC if desired). If you hit, you must immediately attempt a Climb check (DC = wall\'s DC + 10). Success indicates that you catch the falling character, but his or her total weight, including equipment, cannot exceed your heavy load limit or you automatically fall. If you fail your Climb check by 4 or less, you fail to stop the character\'s fall but don\'t lose your grip on the wall. If you fail by 5 or more, you fail to stop the character\'s fall and begin falling as well.</p>\n','Climbing is part of movement, so it\'s generally part of a move action (and may be combined with other types of movement in a move action). Each move action that includes any climbing requires a separate Climb check. Catching yourself or another falling character doesn\'t take an action.',NULL,'You can use a rope to haul a character upward (or lower a character) through sheer strength. You can lift double your maximum load in this manner.A halfling has a +2 racial bonus on Climb checks because halflings are agile and surefooted.The master of a lizard familiar gains a +3 bonus on Climb checks.If you have the Athletic feat, you get a +2 bonus on Climb checks.A creature with a climb speed has a +8 racial bonus on all Climb checks. The creature must make a Climb check to climb any wall or slope with a DC higher than 0, but it always can choose to take 10, even if rushed or threatened while climbing. If a creature with a climb speed chooses an accelerated climb (see above), it moves at double its climb speed (or at its land speed, whichever is slower) and makes a single Climb check at a -5 penalty. Such a creature retains its Dexterity bonus to Armor Class (if any) while climbing, and opponents get no special bonus to their attacks against it. It cannot, however, use the run action while climbing.',NULL,'If you have 5 or more ranks in Use Rope, you get a +2 bonus on Climb checks made to climb a rope, a knotted rope, or a rope-and-wall combination.','\n      <p>The character can climb otherwise unclimbable surfaces.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>DC</b><br/></td> <td><b>Surface</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>70<br/></td>\n<td>A perfectly smooth, flat, vertical surface<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>100<br/></td>\n<td>A perfectly smooth, flat, overhang or ceiling<br/></td>\n\n</tr>\n</table>\n      <div topic=\"Rapid Climbing\" level=\"8\"><p><b>Rapid Climbing:</b> A character can climb his or her speed as a move-equivalent action, or double his or her speed as a full-round action (requiring two Climb checks), but the character takes a -20 penalty on his or her check.</p><p>Special: The Legendary Climber feat allows a character to ignore any penalties for accelerated or rapid climbing.</p><p/>\n</div>\n    ',NULL,'\n      <div topic=\"Climb\" level=\"3\"><p><h3>Climb (Str; Armor Check Penalty)</h3></p><div topic=\"Check\" level=\"8\"><p> With a successful Climb check, you can advance up, down, or across a slope, a wall, or some other steep incline (or even a ceiling with handholds) at one-quarter your normal speed. A slope is considered to be any incline at an angle measuring less than 60 degrees; a wall is any incline at an angle measuring 60 degrees or more.</p><p>A Climb check that fails by 4 or less means that you make no progress, and one that fails by 5 or more means that you fall from whatever height you have already attained.</p><p>A climber\'s kit gives you a +2 circumstance bonus on Climb checks.</p><p>The DC of the check depends on the conditions of the climb. Compare the task with those on the following table to determine an appropriate DC.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Climb DC</b> <br/></td>\n<td><b>Example Surface or Activity</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>0<br/></td>\n<td>A slope too steep to walk up, or a knotted rope with a wall to brace against.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5<br/></td>\n<td>A rope with a wall to brace against, or a knotted rope, or a rope affected by the <i>rope trick</i> spell.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>A surface with ledges to hold on to and stand on, such as a very rough wall or a ship\'s rigging.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Any surface with adequate handholds and footholds (natural or artificial), such as a very rough natural rock surface or a tree, or an unknotted rope, or pulling yourself up when dangling by your hands.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>An uneven surface with some narrow handholds and footholds, such as a typical wall in a dungeon or ruins.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>25<br/></td>\n<td>A rough surface, such as a natural rock wall or a brick wall.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>25<br/></td>\n<td>An overhang or ceiling with handholds but no footholds.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>-<br/></td>\n<td>A perfectly smooth, flat, vertical surface cannot be climbed.<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Climb DC Modifier</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Example Surface or Activity</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>-10<br/></td>\n<td>Climbing a chimney (artificial or natural) or other location where you can brace against two opposite walls (reduces DC by 10).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>-5<br/></td>\n<td>Climbing a corner where you can brace against perpendicular walls (reduces DC by 5).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>+5<br/></td>\n<td>Surface is slippery (increases DC by 5).<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1These modifiers are cumulative; use any that apply.<br/></td>\n\n</tr>\n</table><p/><p>You need both hands free to climb, but you may cling to a wall with one hand while you cast a spell or take some other action that requires only one hand. While climbing, you can\'t move to avoid a blow, so you lose your Dexterity bonus to AC (if any). You also can\'t use a shield while climbing.</p><p>Any time you take damage while climbing, make a Climb check against the DC of the slope or wall. Failure means you fall from your current height and sustain the appropriate falling damage.</p><p><i>Accelerated Climbing:</i> You try to climb more quickly than normal. By accepting a -5 penalty, you can move half your speed (instead of one-quarter your speed).</p><p><i>Making Your Own Handholds and Footholds:</i> You can make your own handholds and footholds by pounding pitons into a wall. Doing so takes 1 minute per piton, and one piton is needed per 3 feet of distance. As with any surface that offers handholds and footholds, a wall with pitons in it has a DC of 15. In the same way, a climber with a handaxe or similar implement can cut handholds in an ice wall.</p><p><i>Catching Yourself When Falling:</i> It\'s practically impossible to catch yourself on a wall while falling. Make a Climb check (DC = wall\'s DC + 20) to do so. It\'s much easier to catch yourself on a slope (DC = slope\'s DC + 10).</p><p><i>Catching a Falling Character While Climbing:</i> If someone climbing above you or adjacent to you falls, you can attempt to catch the falling character if he or she is within your reach. Doing so requires a successful melee touch attack against the falling character (though he or she can voluntarily forego any Dexterity bonus to AC if desired). If you hit, you must immediately attempt a Climb check (DC = wall\'s DC + 10). Success indicates that you catch the falling character, but his or her total weight, including equipment, cannot exceed your heavy load limit or you automatically fall. If you fail your Climb check by 4 or less, you fail to stop the character\'s fall but don\'t lose your grip on the wall. If you fail by 5 or more, you fail to stop the character\'s fall and begin falling as well.</p>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> Climbing is part of movement, so it\'s generally part of a move action (and may be combined with other types of movement in a move action). Each move action that includes any climbing requires a separate Climb check. Catching yourself or another falling character doesn\'t take an action.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can use a rope to haul a character upward (or lower a character) through sheer strength. You can lift double your maximum load in this manner.</p><p>A halfling has a +2 racial bonus on Climb checks because halflings are agile and surefooted.</p><p>The master of a lizard familiar gains a +3 bonus on Climb checks.</p><p>If you have the Athletic feat, you get a +2 bonus on Climb checks.</p><p>A creature with a climb speed has a +8 racial bonus on all Climb checks. The creature must make a Climb check to climb any wall or slope with a DC higher than 0, but it always can choose to take 10, even if rushed or threatened while climbing. If a creature with a climb speed chooses an accelerated climb (see above), it moves at double its climb speed (or at its land speed, whichever is slower) and makes a single Climb check at a -5 penalty. Such a creature retains its Dexterity bonus to Armor Class (if any) while climbing, and opponents get no special bonus to their attacks against it. It cannot, however, use the run action while climbing.</p>\n</div><div topic=\"Synergy\" level=\"8\"><p><b>Synergy:</b> If you have 5 or more ranks in Use Rope, you get a +2 bonus on Climb checks made to climb a rope, a knotted rope, or a rope-and-wall combination.</p>\n</div><div topic=\"Epic Use\" level=\"5\"><p><h5>Epic Use</h5></p><p>The character can climb otherwise unclimbable surfaces.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>DC</b><br/></td> <td><b>Surface</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>70<br/></td>\n<td>A perfectly smooth, flat, vertical surface<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>100<br/></td>\n<td>A perfectly smooth, flat, overhang or ceiling<br/></td>\n\n</tr>\n</table><div topic=\"Rapid Climbing\" level=\"8\"><p><b>Rapid Climbing:</b> A character can climb his or her speed as a move-equivalent action, or double his or her speed as a full-round action (requiring two Climb checks), but the character takes a -20 penalty on his or her check.</p><p>Special: The Legendary Climber feat allows a character to ignore any penalties for accelerated or rapid climbing.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (6,'Concentration',NULL,'Con','No','No','No',NULL,'<p> You must make a Concentration check whenever you might potentially be distracted (by taking damage, by harsh weather, and so on) while engaged in some action that requires your full attention. Such actions include casting a spell, concentrating on an active spell, directing a spell, using a spell-like ability, or using a skill that would provoke an attack of opportunity. In general, if an action wouldn\'t normally provoke an attack of opportunity, you need not make a Concentration check to avoid being distracted.</p><p>If the Concentration check succeeds, you may continue with the action as normal. If the check fails, the action automatically fails and is wasted. If you were in the process of casting a spell, the spell is lost. If you were concentrating on an active spell, the spell ends as if you had ceased concentrating on it. If you were directing a spell, the direction fails but the spell remains active. If you were using a spell-like ability, that use of the ability is lost. A skill use also fails, and in some cases a failed skill check may have other ramifications as well.</p><p>The table below summarizes various types of distractions that cause you to make a Concentration check. If the distraction occurs while you are trying to cast a spell, you must add the level of the spell you are trying to cast to the appropriate Concentration DC. If more than one type of distraction is present, make a check for each one; any failed Concentration check indicates that the task is not completed.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Concentration DC</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Distraction</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + damage dealt<br/></td>\n<td>Damaged during the action.<sup><b>2</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + half of continuous<br/></td>\n<td>Taking continuous damage during the damage last dealt action.<sup><b>3</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting spell\'s save DC<br/></td>\n<td>Distracted by nondamaging spell.<sup><b>4</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>Vigorous motion (on a moving mount, taking a bouncy wagon ride, in a small boat in rough water, belowdecks in a stormtossed ship).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Violent motion (on a galloping horse, taking a very rough wagon ride, in a small boat in rapids, on the deck of a storm-tossed ship).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Extraordinarily violent motion (earthquake<i>)</i>.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Entangled.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Grappling or pinned. (You can cast only spells without somatic components for which you have any required material component in hand.)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5<br/></td>\n<td>Weather is a high wind carrying blinding rain or sleet.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>Weather is wind-driven hail, dust, or debris.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting spell\'s save DC<br/></td>\n<td>Weather caused by a spell, such as <i>storm of vengeance</i>.<b>4</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 If you are trying to cast, concentrate on, or direct a spell when the distraction occurs, add the level of the spell to the indicated DC.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">2 Such as during the casting of a spell with a casting time of 1 round or more, or the execution of an activity that takes more than a single full-round action (such as Disable Device). Also, damage stemming from an attack of opportunity or readied attack made in response to the spell being cast (for spells with a casting time of 1 action) or the action being taken (for activities requiring no more than a full-round action).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">3 Such as from <i>acid arrow</i>.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">4 If the spell allows no save, use the save DC it would have if it did allow a save.<br/></td>\n\n</tr>\n</table><p/>\n','None. Making a Concentration check doesn\'t take an action; it is either a free action (when attempted reactively) or part of another action (when attempted actively).','Yes, though a success doesn\'t cancel the effect of a previous failure, such as the loss of a spell you were casting or the disruption of a spell you were concentrating on.','You can use Concentration to cast a spell, use a spell-like ability, or use a skill defensively, so as to avoid attacks of opportunity altogether. This doesn\'t apply to other actions that might provoke attacks of opportunity.The DC of the check is 15 (plus the spell\'s level, if casting a spell or using a spell-like ability defensively). If the Concentration check succeeds, you may attempt the action normally without provoking any attacks of opportunity. A successful Concentration check still doesn\'t allow you to take 10 on another check if you are in a stressful situation; you must make the check normally. If the Concentration check fails, the related action also automatically fails (with any appropriate ramifications), and the action is wasted, just as if your concentration had been disrupted by a distraction.A character with the Combat Casting feat gets a +4 bonus on Concentration checks made to cast a spell or use a spell-like ability while on the defensive or while grappling or pinned.',NULL,NULL,'\n      <p>The character can cast spells with somatic components even while grappled.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td> <td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Cast spell with somatic component while grappled<br/></td>\n<td>50 + spell level<br/></td>\n\n</tr>\n</table>\n      <p/>\n      <p/>\n    ',NULL,'\n      <div topic=\"Concentration\" level=\"3\"><p><h3>Concentration (Con)</h3></p><div topic=\"Check\" level=\"8\"><p> You must make a Concentration check whenever you might potentially be distracted (by taking damage, by harsh weather, and so on) while engaged in some action that requires your full attention. Such actions include casting a spell, concentrating on an active spell, directing a spell, using a spell-like ability, or using a skill that would provoke an attack of opportunity. In general, if an action wouldn\'t normally provoke an attack of opportunity, you need not make a Concentration check to avoid being distracted.</p><p>If the Concentration check succeeds, you may continue with the action as normal. If the check fails, the action automatically fails and is wasted. If you were in the process of casting a spell, the spell is lost. If you were concentrating on an active spell, the spell ends as if you had ceased concentrating on it. If you were directing a spell, the direction fails but the spell remains active. If you were using a spell-like ability, that use of the ability is lost. A skill use also fails, and in some cases a failed skill check may have other ramifications as well.</p><p>The table below summarizes various types of distractions that cause you to make a Concentration check. If the distraction occurs while you are trying to cast a spell, you must add the level of the spell you are trying to cast to the appropriate Concentration DC. If more than one type of distraction is present, make a check for each one; any failed Concentration check indicates that the task is not completed.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Concentration DC</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Distraction</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + damage dealt<br/></td>\n<td>Damaged during the action.<sup><b>2</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + half of continuous<br/></td>\n<td>Taking continuous damage during the damage last dealt action.<sup><b>3</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting spell\'s save DC<br/></td>\n<td>Distracted by nondamaging spell.<sup><b>4</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>Vigorous motion (on a moving mount, taking a bouncy wagon ride, in a small boat in rough water, belowdecks in a stormtossed ship).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Violent motion (on a galloping horse, taking a very rough wagon ride, in a small boat in rapids, on the deck of a storm-tossed ship).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Extraordinarily violent motion (earthquake<i>)</i>.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Entangled.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Grappling or pinned. (You can cast only spells without somatic components for which you have any required material component in hand.)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5<br/></td>\n<td>Weather is a high wind carrying blinding rain or sleet.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10<br/></td>\n<td>Weather is wind-driven hail, dust, or debris.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting spell\'s save DC<br/></td>\n<td>Weather caused by a spell, such as <i>storm of vengeance</i>.<b>4</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 If you are trying to cast, concentrate on, or direct a spell when the distraction occurs, add the level of the spell to the indicated DC.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">2 Such as during the casting of a spell with a casting time of 1 round or more, or the execution of an activity that takes more than a single full-round action (such as Disable Device). Also, damage stemming from an attack of opportunity or readied attack made in response to the spell being cast (for spells with a casting time of 1 action) or the action being taken (for activities requiring no more than a full-round action).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">3 Such as from <i>acid arrow</i>.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">4 If the spell allows no save, use the save DC it would have if it did allow a save.<br/></td>\n\n</tr>\n</table><p/>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> None. Making a Concentration check doesn\'t take an action; it is either a free action (when attempted reactively) or part of another action (when attempted actively).</p>\n</div><div topic=\"Try Again\" level=\"8\"><p><b>Try Again:</b> Yes, though a success doesn\'t cancel the effect of a previous failure, such as the loss of a spell you were casting or the disruption of a spell you were concentrating on.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can use Concentration to cast a spell, use a spell-like ability, or use a skill defensively, so as to avoid attacks of opportunity altogether. This doesn\'t apply to other actions that might provoke attacks of opportunity.</p><p>The DC of the check is 15 (plus the spell\'s level, if casting a spell or using a spell-like ability defensively). If the Concentration check succeeds, you may attempt the action normally without provoking any attacks of opportunity. A successful Concentration check still doesn\'t allow you to take 10 on another check if you are in a stressful situation; you must make the check normally. If the Concentration check fails, the related action also automatically fails (with any appropriate ramifications), and the action is wasted, just as if your concentration had been disrupted by a distraction.</p><p>A character with the Combat Casting feat gets a +4 bonus on Concentration checks made to cast a spell or use a spell-like ability while on the defensive or while grappling or pinned.</p>\n</div><div topic=\"Epic Use\" level=\"5\"><p><h5>Epic Use</h5></p><p>The character can cast spells with somatic components even while grappled.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td> <td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Cast spell with somatic component while grappled<br/></td>\n<td>50 + spell level<br/></td>\n\n</tr>\n</table><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (7,'Concentration',NULL,'Con','Yes','No','No','<p> You are particularly good at focusing your mind.</p><p>The following are additional uses for the concentration skill.</p>\n','<p> You must make a Concentration check whenever you might potentially be distracted (by taking damage, by harsh weather, and so on) while engaged in some action that requires your full attention. Such actions include manifesting a power, concentrating on an active power, directing a power, or using a psi-like ability.</p><p>If the Concentration check succeeds, you can continue with the action as normal. If the check fails, the action automatically fails and is wasted. If you were in the process of manifesting a power, the power points are lost. If you were concentrating on an active power, the power ends as if you had ceased concentrating on it. If you were directing a power, the direction fails but the power remains active. If you were using a psi-like ability, that use of the ability is lost.</p><p>The table below summarizes various types of distractions that cause you to make a Concentration check. If the distraction occurs while you are trying to manifest a power, you must add the level of the power you are trying to manifest to the appropriate Concentration DC.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Concentration DC</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Distraction</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + damage dealt<br/></td>\n<td>Damaged during the action.<sup><b>2</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + half of continuous damage last dealt<br/></td>\n<td>Taking continuous damage during the action.<sup><b>3</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15 + power level<br/></td>\n<td>Attempting to manifest a power without its display.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Entangled.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting power\'s save DC<br/></td>\n<td>Distracted by nondamaging power.<sup><b>4</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Gain psionic focus.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Grappling or pinned. (You can manifest powers normally unless you fail your Concentration check.)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting power\'s save DC<br/></td>\n<td>Weather caused by power<sup><b>4</b></sup><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 If you are trying to manifest, concentrate on, or direct a power when the distraction occurs, add the level of the power to the indicated DC.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">2 Such as during the manifestation of a power with a manifesting time of 1 round or more. Also from an attack of opportunity or readied attack made in response to the power being manifested (for powers with a manifesting time of 1 action) or the action being taken (for activities requiring no more than a full-round action).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">3 Such as from standing in natural fire or lava.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">4 If the power allows no save, use the save DC it would have if it did allow a save.<br/></td>\n\n</tr>\n</table><p/><p><i>Gain Psionic Focus:</i> Merely holding a reservoir of psionic power points in mind gives psionic characters a special energy. Psionic characters can put that energy to work without actually paying a power point cost-they can become psionically focused as a special use of the Concentration skill.</p><p>If you have 1 or more power points available, you can meditate to attempt to become psionically focused. The DC to become psionically focused is 20. Meditating is a full-round action that provokes attacks of opportunity. When you are psionically focused, you can expend your focus on any single Concentration check you make thereafter. When you expend your focus in this manner, your Concentration check is treated as if you rolled a 15. It\'s like taking 10, except that the number you add to your Concentration modifier is 15. You can also expend your focus to gain the benefit of a psionic feat-many psionic feats are activated in this way.</p><p>Once you are psionically focused, you remain focused until you expend your focus, become unconscious, or go to sleep (or enter a meditative trance, in the case of elans), or until your power point reserve drops to 0.</p>\n','Usually none. In most cases, making a Concentration check doesn\'t require an action; it is either a free action (when attempted reactively) or part of another action (when attempted actively). Meditating to gain psionic focus is a full-round action.','Yes, though a success doesn\'t cancel the effects of a previous failure, such as the loss of the power points for a power being manifested or the disruption of a power being concentrated on.','You can use Concentration to manifest a power or use a psi-like ability defensively, so as to avoid attacks of opportunity altogether. The DC of the check is 15 + the power\'s level. If the Concentration check succeeds, you can manifest normally without provoking any attacks of opportunity. If the Concentration check fails, the power also automatically fails and the power points are wasted, just as if your concentration had been disrupted by a distraction.A character with the Combat Manifestation feat gets a +4 bonus on Concentration checks made to manifest a power or use a psi-like ability while on the defensive or while grappling or pinned.',NULL,'If you have 5 or more ranks in Concentration, you get a +2 bonus on Autohypnosis checks.',NULL,NULL,'\n      <div topic=\"Concentration, Psionic\" level=\"3\"><p><h3>Concentration, Psionic (Con; Psionic)</h3></p><div topic=\"Description\" level=\"8\"><p> You are particularly good at focusing your mind.</p><p>The following are additional uses for the concentration skill.</p>\n</div><div topic=\"Check\" level=\"8\"><p> You must make a Concentration check whenever you might potentially be distracted (by taking damage, by harsh weather, and so on) while engaged in some action that requires your full attention. Such actions include manifesting a power, concentrating on an active power, directing a power, or using a psi-like ability.</p><p>If the Concentration check succeeds, you can continue with the action as normal. If the check fails, the action automatically fails and is wasted. If you were in the process of manifesting a power, the power points are lost. If you were concentrating on an active power, the power ends as if you had ceased concentrating on it. If you were directing a power, the direction fails but the power remains active. If you were using a psi-like ability, that use of the ability is lost.</p><p>The table below summarizes various types of distractions that cause you to make a Concentration check. If the distraction occurs while you are trying to manifest a power, you must add the level of the power you are trying to manifest to the appropriate Concentration DC.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Concentration DC</b>\n<sup><b>1</b></sup><br/></td>\n<td><b>Distraction</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + damage dealt<br/></td>\n<td>Damaged during the action.<sup><b>2</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10 + half of continuous damage last dealt<br/></td>\n<td>Taking continuous damage during the action.<sup><b>3</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15 + power level<br/></td>\n<td>Attempting to manifest a power without its display.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15<br/></td>\n<td>Entangled.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting power\'s save DC<br/></td>\n<td>Distracted by nondamaging power.<sup><b>4</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Gain psionic focus.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20<br/></td>\n<td>Grappling or pinned. (You can manifest powers normally unless you fail your Concentration check.)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Distracting power\'s save DC<br/></td>\n<td>Weather caused by power<sup><b>4</b></sup><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 If you are trying to manifest, concentrate on, or direct a power when the distraction occurs, add the level of the power to the indicated DC.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">2 Such as during the manifestation of a power with a manifesting time of 1 round or more. Also from an attack of opportunity or readied attack made in response to the power being manifested (for powers with a manifesting time of 1 action) or the action being taken (for activities requiring no more than a full-round action).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">3 Such as from standing in natural fire or lava.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">4 If the power allows no save, use the save DC it would have if it did allow a save.<br/></td>\n\n</tr>\n</table><p/><p><i>Gain Psionic Focus:</i> Merely holding a reservoir of psionic power points in mind gives psionic characters a special energy. Psionic characters can put that energy to work without actually paying a power point cost-they can become psionically focused as a special use of the Concentration skill.</p><p>If you have 1 or more power points available, you can meditate to attempt to become psionically focused. The DC to become psionically focused is 20. Meditating is a full-round action that provokes attacks of opportunity. When you are psionically focused, you can expend your focus on any single Concentration check you make thereafter. When you expend your focus in this manner, your Concentration check is treated as if you rolled a 15. It\'s like taking 10, except that the number you add to your Concentration modifier is 15. You can also expend your focus to gain the benefit of a psionic feat-many psionic feats are activated in this way.</p><p>Once you are psionically focused, you remain focused until you expend your focus, become unconscious, or go to sleep (or enter a meditative trance, in the case of elans), or until your power point reserve drops to 0.</p>\n</div><div topic=\"Action\" level=\"8\"><p><b>Action:</b> Usually none. In most cases, making a Concentration check doesn\'t require an action; it is either a free action (when attempted reactively) or part of another action (when attempted actively). Meditating to gain psionic focus is a full-round action.</p>\n</div><div topic=\"Try Again\" level=\"8\"><p><b>Try Again:</b> Yes, though a success doesn\'t cancel the effects of a previous failure, such as the loss of the power points for a power being manifested or the disruption of a power being concentrated on.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can use Concentration to manifest a power or use a psi-like ability defensively, so as to avoid attacks of opportunity altogether. The DC of the check is 15 + the power\'s level. If the Concentration check succeeds, you can manifest normally without provoking any attacks of opportunity. If the Concentration check fails, the power also automatically fails and the power points are wasted, just as if your concentration had been disrupted by a distraction.</p><p>A character with the Combat Manifestation feat gets a +4 bonus on Concentration checks made to manifest a power or use a psi-like ability while on the defensive or while grappling or pinned.</p>\n</div><div topic=\"Synergy\" level=\"8\"><p><b>Synergy:</b> If you have 5 or more ranks in Concentration, you get a +2 bonus on Autohypnosis checks.</p><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 CombinedSkills');
INSERT INTO skill VALUES (8,'Craft','alchemy,armorsmithing,blacksmithing,dreamweaving,gemcutting,leatherworking,metalworking,painting,sculpting,shipmaking,stonemasonry,stoneworking,trapmaking,weaponsmithing','Int','No','No','No','<p> Like Knowledge, Perform, and Profession, Craft is actually a number of separate skills. You could have several Craft skills, each with its own ranks, each purchased as a separate skill.</p><p>A Craft skill is specifically focused on creating something. If nothing is created by the endeavor, it probably falls under the heading of a Profession skill.</p>\n','<p> You can practice your trade and make a decent living, earning about half your check result in gold pieces per week of dedicated work. You know how to use the tools of your trade, how to perform the craft\'s daily tasks, how to supervise untrained helpers, and how to handle common problems. (Untrained laborers and assistants earn an average of 1 silver piece per day.)</p><p>The basic function of the Craft skill, however, is to allow you to make an item of the appropriate type. The DC depends on the complexity of the item to be created. The DC, your check results, and the price of the item determine how long it takes to make a particular item. The item\'s finished price also determines the cost of raw materials.</p><p>In some cases, the <i>fabricate</i> spell can be used to achieve the results of a Craft check with no actual check involved. However, you must make an appropriate Craft check when using the spell to make articles requiring a high degree of craftsmanship.</p><p>A successful Craft check related to woodworking in conjunction with the casting of the <i>ironwood</i> spell enables you to make wooden items that have the strength of steel.</p><p>When casting the spell <i>minor creation</i>, you must succeed on an appropriate Craft check to make a complex item.</p><p>All crafts require artisan\'s tools to give the best chance of success. If improvised tools are used, the check is made with a -2 circumstance penalty. On the other hand, masterwork artisan\'s tools provide a +2 circumstance bonus on the check.</p><p>To determine how much time and money it takes to make an item, follow these steps.</p><p>1. Find the item\'s price. Put the price in silver pieces (1 gp = 10 sp).</p><p>2. Find the DC from the table below.</p><p>3. Pay one-third of the item\'s price for the cost of raw materials.</p><p>4. Make an appropriate Craft check representing one week\'s work. If the check succeeds, multiply your check result by the DC. If the result x the DC equals the price of the item in sp, then you have completed the item. (If the result x the DC equals double or triple the price of the item in silver pieces, then you\'ve completed the task in one-half or one-third of the time. Other multiples of the DC reduce the time in the same manner.) If the result x the DC doesn\'t equal the price, then it represents the progress you\'ve made this week. Record the result and make a new Craft check for the next week. Each week, you make more progress until your total reaches the price of the item in silver pieces.</p><p>If you fail a check by 4 or less, you make no progress this week.</p><p>If you fail by 5 or more, you ruin half the raw materials and have to pay half the original raw material cost again.</p><p><i>Progress by the Day:</i> You can make checks by the day instead of by the week. In this case your progress (check result x DC) is in copper pieces instead of silver pieces.</p><p><i>Creating Masterwork Items:</i> You can make a masterwork item-a weapon, suit of armor, shield, or tool that conveys a bonus on its use through its exceptional craftsmanship, not through being magical. To create a masterwork item, you create the masterwork component as if it were a separate item in addition to the standard item. The masterwork component has its own price (300 gp for a weapon or 150 gp for a suit of armor or a shield) and a Craft DC of 20. Once both the standard component and the masterwork component are completed, the masterwork item is finished. <i>Note:</i> The cost you pay for the masterwork component is one-third of the given amount, just as it is for the cost in raw materials.</p><p><i>Repairing Items:</i> Generally, you can repair an item by making checks against the same DC that it took to make the item in the first place. The cost of repairing an item is one-fifth of the item\'s price.</p><p/><p>When you use the Craft skill to make a particular sort of item, the DC for checks involving the creation of that item are typically as given on the following table.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Item</b> <br/></td>\n<td><b>Craft Skill</b> <br/></td>\n<td><b>Craft DC</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Acid<br/></td>\n<td>Alchemy<b>1</b> <br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Alchemist\'s fire, smokestick, or tindertwig<br/></td>\n<td>Alchemy<b>1</b> <br/></td>\n<td>20<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Antitoxin, sunrod, tanglefoot bag, or thunderstone<br/></td>\n<td>Alchemy<b>1</b> <br/></td>\n<td>25<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Armor or shield<br/></td>\n<td>Armorsmithing<br/></td>\n<td>10 + AC bonus<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Longbow or shortbow<br/></td>\n<td>Bowmaking<br/></td>\n<td>12<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Composite longbow or composite shortbow<br/></td>\n<td>Bowmaking<br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Composite longbow or composite shortbow with high strength rating<br/></td>\n<td>Bowmaking<br/></td>\n<td>15 + (2 x rating)<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Crossbow<br/></td>\n<td>Weaponsmithing<br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Simple melee or thrown weapon<br/></td>\n<td>Weaponsmithing<br/></td>\n<td>12<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Martial melee or thrown weapon<br/></td>\n<td>Weaponsmithing<br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Exotic melee or thrown weapon<br/></td>\n<td>Weaponsmithing<br/></td>\n<td>18<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Mechanical trap<br/></td>\n<td>Trapmaking<br/></td>\n<td>Varies<sup><b>2</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Very simple item (wooden spoon)<br/></td>\n<td>Varies<br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Typical item (iron pot)<br/></td>\n<td>Varies<br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>High-quality item (bell)<br/></td>\n<td>Varies<br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Complex or superior item (lock)<br/></td>\n<td>Varies<br/></td>\n<td>20<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"2\">\n<td colspan=\"3\">1 You must be a spellcaster to craft any of these items.<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"2\">\n<td colspan=\"3\">2 Traps have their own rules for construction.<br/></td>\n\n</tr>\n</table><p/>\n','Does not apply. Craft checks are made by the day or week (see above).','Yes, but each time you miss by 5 or more, you ruin half the raw materials and have to pay half the original raw material cost again.','A dwarf has a +2 racial bonus on Craft checks that are related to stone or metal, because dwarves are especially capable with stonework and metalwork.A gnome has a +2 racial bonus on Craft (alchemy) checks because gnomes have sensitive noses.You may voluntarily add +10 to the indicated DC to craft an item. This allows you to create the item more quickly (since you\'ll be multiplying this higher DC by your Craft check result to determine progress). You must decide whether to increase the DC before you make each weekly or daily check.To make an item using Craft (alchemy), you must have alchemical equipment and be a spellcaster. If you are working in a city, you can buy what you need as part of the raw materials cost to make the item, but alchemical equipment is difficult or impossible to come by in some places. Purchasing and maintaining an alchemist\'s lab grants a +2 circumstance bonus on Craft (alchemy) checks because you have the perfect tools for the job, but it does not affect the cost of any items made using the skill.',NULL,'If you have 5 ranks in a Craft skill, you get a +2 bonus on Appraise checks related to items made with that Craft skill.','\n      <p>The character can craft items more quickly than normal.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td> <td><b>DC</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Quick creation<br/></td>\n<td>+10 or more to DC<br/></td>\n\n</tr>\n</table>\n      <div topic=\"Quick Creation\" level=\"8\"><p><b>Quick Creation:</b> A character can voluntarily increase the DC of crafting an item by any multiple of 10. This allows the character to create an item more quickly (since he or she will be multiplying this higher DC by his or her skill check result to determine progress). The character must decide the increase to the DC before making the check.</p><p/>\n</div>\n      <div topic=\"Craft\" level=\"8\"><p>Craft (Alchemy)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Task</b><br/></td>\n<td><b>DC (or DC Modifier)</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Create augmented substance<br/></td>\n<td>+20 or more to DC<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td/>\n